import React, { useState, useEffect } from "react";

export default function ChooseName({
  characterName,
  selectedImage,
  onNameChange,
  onContinue,
  onPrev,
  selectedRace,
}) {
  const [isValidName, setIsValidName] = useState(false);

  const nameRegex = /^[A-Za-z]{3,15}$/;
  const defaultImage = "/raceicon/noimage.jpg";

  useEffect(() => {
    setIsValidName(nameRegex.test(characterName.trim()));
  }, [characterName]);

  const getImageSrc = () => {
    if (!selectedRace || !selectedImage) return defaultImage;
    return `/raceicon/${selectedRace.toLowerCase()}_${selectedImage}.png`;
  };

  return (
    <div className="flex flex-col items-center justify-between min-h-[520px] backdrop-blur-sm px-4 py-4 overflow-hidden">
      <div className="w-full max-w-3xl flex flex-col items-center">
        <h1 className="text-3xl font-bold text-white mb-4 text-center hero-title">
          Choose Your Name
        </h1>

      {selectedImage && selectedRace && (
        <div className="mb-4">
          <img
            src={getImageSrc()}
            alt="Selected character"
            className="w-60 h-60 object-cover rounded-lg"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = defaultImage;
            }}
          />
        </div>
      )}

      <input
        type="text"
        value={characterName}
        onChange={(e) => onNameChange(e.target.value)}
        placeholder="Enter your character's name"
        className="w-80 p-3 rounded-lg bg-gray-900/80 text-white text-lg placeholder-gray-400 border border-yellow-700/30 focus:outline-none focus:ring-2 focus:ring-yellow-400"
      />

      {!isValidName && characterName && (
        <p className="text-red-500 mt-2 text-sm">
          Name must be 3–15 letters, alphabets only.
        </p>
      )}

      <div className="flex space-x-4 mt-6">
        <button
          onClick={onPrev}
          className="px-6 py-2 font-semibold rounded-lg action-ghost text-yellow-200"
        >
          Previous
        </button>

        <button
          onClick={onContinue}
          disabled={!isValidName}
          className={`px-6 py-2 font-semibold rounded-lg shadow-lg transition duration-300 ${
            isValidName
              ? "action-primary text-white"
              : "bg-gray-700 text-gray-300 cursor-not-allowed"
          }`}
        >
          Create Character
        </button>
      </div>
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import Sidebar from '../components/Sidebar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import {
  addArenaHistory,
  clearStoredOpponent,
  clearStoredResult,
  clearStoredWager,
  getOrCreateOpponent,
  getOrCreateResult,
  getPlayerStats,
  getStoredHazard,
  getStoredWager,
  incrementRivalRecord,
} from '../data/arenaOpponents';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

export default function ArenaResult() {
  const [opponent, setOpponent] = useState(() => getOrCreateOpponent());
  const [result, setResult] = useState(() => getOrCreateResult(opponent));
  const [wager] = useState(() => getStoredWager());
  const [hazard] = useState(() => getStoredHazard());
  const [playerStats, setPlayerStats] = useState(() => getPlayerStats(null));
  const hasLogged = useRef(false);
  const hasAppliedWager = useRef(false);

  useEffect(() => {
    const nextOpponent = getOrCreateOpponent();
    setOpponent(nextOpponent);
    setResult(getOrCreateResult(nextOpponent));
    if (MOCK_AUTH) {
      const username = authService.getCurrentUsername();
      const profile = characterService.getMockProfile(username);
      setPlayerStats(getPlayerStats(profile));
    }
  }, []);

  useEffect(() => {
    if (!opponent || !result || hasLogged.current) {
      return;
    }

    addArenaHistory({
      id: Date.now(),
      outcome: result.outcome,
      opponentName: opponent.name,
      opponentRank: opponent.rank,
      opponentLevel: opponent.level,
      rankChange: result.rankChange,
      hazard: hazard?.name || null,
      wager,
      rewards: result.rewards,
      createdAt: new Date().toISOString(),
    });

    incrementRivalRecord(opponent.name);

    hasLogged.current = true;
  }, [hazard, opponent, result, wager]);

  useEffect(() => {
    if (!MOCK_AUTH || hasAppliedWager.current || wager <= 0) {
      return;
    }

    const username = authService.getCurrentUsername();
    const profile = characterService.getMockProfile(username);
    if (!profile?.stats) {
      return;
    }
    const currentGold = profile?.stats?.gold ?? 0;
    const delta = result.outcome === 'Victory' ? wager : -wager;
    const nextGold = Math.max(0, currentGold + delta);
    characterService.updateMockProfile({
      stats: {
        ...profile.stats,
        gold: nextGold,
      },
    });
    clearStoredWager();
    hasAppliedWager.current = true;
  }, [result, wager]);

  const handleRematch = () => {
    clearStoredOpponent();
    clearStoredResult();
  };

  const rewardLines = useMemo(() => {
    const base = [...result.rewards];
    if (wager > 0) {
      const wagerLine = result.outcome === 'Victory' ? `Wager payout +${wager * 2} gold` : `Wager lost -${wager} gold`;
      base.push(wagerLine);
    }
    if (hazard?.name) {
      base.push(`Arena hazard: ${hazard.name}`);
    }
    return base;
  }, [hazard, result.rewards, result.outcome, wager]);

  const highlightReel = useMemo(() => {
    if (!opponent || !result) {
      return null;
    }

    if (result.highlightReel) {
      return result.highlightReel;
    }

    const playerTotal = playerStats.reduce((sum, stat) => sum + stat.value, 0);
    const opponentTotal = opponent.stats.reduce((sum, stat) => sum + stat.value, 0);

    const getTopStat = (stats) => {
      return stats.reduce((best, stat) => (stat.value > best.value ? stat : best), stats[0]);
    };

    const playerTop = getTopStat(playerStats);
    const opponentTop = getTopStat(opponent.stats);
    const mvpName = result.outcome === 'Victory' ? 'You' : opponent.name;
    const mvpStat = result.outcome === 'Victory' ? playerTop : opponentTop;

    return {
      mvpName,
      mvpStat,
      totalScore: result.outcome === 'Victory' ? playerTotal : opponentTotal,
      moments: [
        {
          label: 'Opening Exchange',
          detail: `Attack ${playerStats[0].value} vs Defense ${opponent.stats[1].value}`,
        },
        {
          label: 'Signature Push',
          detail: `${mvpName} led with ${mvpStat.label} ${mvpStat.value}`,
        },
        {
          label: 'Final Swing',
          detail: `Rank impact ${result.rankChange}`,
        },
      ],
    };
  }, [opponent, result]);

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Arena Verdict</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">{result.outcome}</h1>
              <p className="mt-3 text-base text-gray-300">
                The duel against {result.opponentName} has concluded. Review your rewards and rank shift.
              </p>
            </div>
            <div className="flex flex-wrap gap-2 text-xs text-gray-300">
              <span className="court-chip rounded-full px-3 py-2">Wager: {wager || 0}g</span>
              <span className="court-chip rounded-full px-3 py-2">Hazard: {hazard?.name || 'Unknown'}</span>
            </div>
          </div>

          <div className="mt-8 grid gap-6 sm:grid-cols-2">
            <div className="image-panel image-panel-arena ornament-frame p-6">
              <div className="image-panel-content">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Opponent</p>
              <p className="mt-2 text-2xl font-semibold text-white">{opponent.name}</p>
              <p className="mt-1 text-sm text-gray-300">Level {opponent.level} · Rank {opponent.rank}</p>
              <div className="mt-4 h-40 overflow-hidden rounded-xl border border-yellow-700/30 bg-gray-900/70">
                <img
                  src={opponent.image}
                  alt="Opponent portrait"
                  className="h-full w-full object-contain"
                  onError={(event) => {
                    event.target.onerror = null;
                    event.target.src = '/raceicon/noimage.jpg';
                  }}
                />
              </div>
              </div>
            </div>
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Rewards</p>
              <ul className="mt-3 space-y-2 text-sm text-gray-300">
                {rewardLines.map((reward) => (
                  <li key={reward} className="rounded-lg border border-yellow-700/20 bg-gray-950/60 px-3 py-2">
                    {reward}
                  </li>
                ))}
              </ul>
              <div className="mt-6 rounded-xl border border-yellow-700/30 bg-gray-950/70 px-4 py-3">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Rank Change</p>
                <p className="mt-2 text-2xl font-semibold text-yellow-300">{result.rankChange}</p>
              </div>
            </div>
          </div>

          {highlightReel && (
            <div className="mt-6 rounded-2xl border border-yellow-700/30 bg-gray-900/80 p-6">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div>
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Highlight Reel</p>
                  <h2 className="mt-2 text-2xl font-semibold text-white">MVP Recap</h2>
                </div>
                <div className="rounded-full border border-yellow-700/40 bg-gray-950/70 px-3 py-1 text-xs text-yellow-200">
                  MVP: {highlightReel.mvpName}
                </div>
              </div>
              <div className="mt-4 grid gap-4 sm:grid-cols-2">
                <div className="rounded-xl border border-yellow-700/20 bg-gray-950/60 p-4">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">MVP Stat</p>
                  <p className="mt-2 text-2xl font-semibold text-white">
                    {highlightReel.mvpStat.label} {highlightReel.mvpStat.value}
                  </p>
                  <p className="mt-1 text-xs text-gray-400">Total score {highlightReel.totalScore}</p>
                </div>
                <div className="rounded-xl border border-yellow-700/20 bg-gray-950/60 p-4">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Key Moments</p>
                  <ul className="mt-2 space-y-2 text-sm text-gray-300">
                    {highlightReel.moments.map((moment) => (
                      <li key={moment.label} className="flex items-center justify-between gap-2">
                        <span className="text-gray-200">{moment.label}</span>
                        <span className="text-xs text-gray-400">{moment.detail}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
          )}

          <div className="mt-8 flex flex-wrap gap-3">
            <Link
              to="/arena/fight"
              onClick={handleRematch}
              className="inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold text-white action-primary"
            >
              Queue Another Fight
            </Link>
            <Link
              to="/arena"
              className="inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold text-yellow-200 action-ghost"
            >
              Back to Arena
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import Sidebar from '../components/Sidebar';
import XpBar from '../components/XpBar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import { getHousingTierById } from '../data/housingData';
import { getFarmXpForLevel } from '../data/farmData';
import { formatDuration, getMiningXpForLevel } from '../data/miningData';
import { getPlayerXpForLevel } from '../data/playerData';
import { ensureGeneralMissions, getMissionProgress, isMissionComplete } from '../data/missionData';
import { getExpeditionLocation } from '../data/expeditionData';
import WorkshopService from '../services/WorkshopService';
import { getWorkshopXpForLevel } from '../data/workshopData';
import { getZoneById, getUnlockedZoneIdsByLevel, zones } from '../data/zonesData';
import { itemsById } from '../data/itemsCatalog';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

export default function DashboardPlayer() {
  const [character, setCharacter] = useState(null);
  const [profile, setProfile] = useState(null);
  const [expeditionSession, setExpeditionSession] = useState(null);
  const [now, setNow] = useState(Date.now());
  const missionSpotlight = useMemo(() => {
    if (!profile?.generalMissions?.length) {
      return [];
    }

    return [...profile.generalMissions]
      .map((mission) => {
        const progress = getMissionProgress(mission, profile);
        const percent = mission.type === 'house'
          ? (isMissionComplete(mission, profile) ? 100 : 0)
          : Math.min(100, Math.round((progress / mission.target) * 100));
        return {
          ...mission,
          progress,
          percent,
          complete: isMissionComplete(mission, profile),
        };
      })
      .sort((a, b) => {
        if (a.complete !== b.complete) {
          return a.complete ? 1 : -1;
        }
        return b.percent - a.percent;
      })
      .slice(0, 3);
  }, [profile]);

  useEffect(() => {
    if (MOCK_AUTH) {
      const username = authService.getCurrentUsername();
      const savedCharacter = characterService.getMockCharacter(username);
      const workshopResult = WorkshopService.processWorkshopQueue({ now: Date.now() });
      if (workshopResult.completedJobs?.length) {
        toast.success(`Workshop ready: ${workshopResult.completedJobs.length} craft(s) completed.`);
      }
      const nextProfile = characterService.getMockProfile(username);
      const { nextMissions, nextMeta, changed } = ensureGeneralMissions(
        nextProfile?.generalMissions,
        nextProfile,
        nextProfile?.generalMissionsMeta
      );
      setCharacter(savedCharacter);

      if (changed) {
        const updated = characterService.updateMockProfile({
          generalMissions: nextMissions,
          generalMissionsMeta: nextMeta,
        });
        setProfile(updated);
      } else {
        setProfile(nextProfile);
      }

      const expeditionKey = `expeditionSession:${username}`;
      const stored = localStorage.getItem(expeditionKey);
      if (stored) {
        try {
          const parsed = JSON.parse(stored);
          if (parsed?.locationId && parsed?.startTime && parsed?.endTime) {
            setExpeditionSession(parsed);
          } else {
            localStorage.removeItem(expeditionKey);
          }
        } catch {
          localStorage.removeItem(expeditionKey);
        }
      }

      const timer = setInterval(() => setNow(Date.now()), 1000);
      return () => clearInterval(timer);
    }
  }, []);


  const activeHouse = getHousingTierById(profile?.houseId || 'starter-cottage');
  const playerLevel = profile?.stats?.level ?? 1;
  const playerXp = profile?.stats?.xp ?? 0;
  const playerXpTarget = getPlayerXpForLevel(playerLevel);
  const miningLevel = profile?.miningLevel ?? 1;
  const miningXp = profile?.miningXp ?? 0;
  const farmLevel = profile?.farmLevel ?? 1;
  const farmXp = profile?.farmXp ?? 0;
  const miningXpTarget = getMiningXpForLevel(miningLevel);
  const farmXpTarget = getFarmXpForLevel(farmLevel);
  const workshopLevel = profile?.workshopLevel ?? 1;
  const workshopXp = profile?.workshopXp ?? 0;
  const workshopXpTarget = getWorkshopXpForLevel(workshopLevel);
  const workshopQueue = profile?.workshopQueue || [];
  const nextWorkshopJob = useMemo(() => {
    if (!workshopQueue.length) {
      return null;
    }
    return [...workshopQueue].sort((a, b) => a.finishAt - b.finishAt)[0] || null;
  }, [workshopQueue]);
  const workshopRemaining = nextWorkshopJob ? Math.max(0, nextWorkshopJob.finishAt - now) : 0;
  const inventory = profile?.inventory || {};
  const inventoryTotals = useMemo(() => {
    const totals = {};
    Object.entries(inventory).forEach(([itemId, amount]) => {
      const item = itemsById[itemId];
      const type = item?.type || 'misc';
      totals[type] = (totals[type] || 0) + (amount || 0);
    });
    return totals;
  }, [inventory]);
  const miningInventoryCount = inventoryTotals.ore || 0;
  const farmInventoryTotal = inventoryTotals['farm-good'] || 0;
  const miningSession = profile?.miningSession || null;
  const miningEndsAt = miningSession?.endAt || 0;
  const miningRemaining = Math.max(0, miningEndsAt - now);
  const miningInProgress = miningRemaining > 0;
  const expeditionLocation = expeditionSession ? getExpeditionLocation(expeditionSession.locationId) : null;
  const expeditionRemaining = expeditionSession
    ? Math.max(0, expeditionSession.endTime - now)
    : 0;
  const expeditionReady = !!expeditionSession && expeditionRemaining === 0;
  const activeZone = getZoneById(profile?.activeZoneId) || zones[0];
  const unlockedZoneIds = profile?.unlockedZones?.length
    ? profile.unlockedZones
    : getUnlockedZoneIdsByLevel(playerLevel);
  const unlockedZones = zones.filter((zone) => unlockedZoneIds.includes(zone.id));

  const handleZoneChange = (event) => {
    if (!profile) {
      return;
    }
    const nextZoneId = event.target.value;
    if (!nextZoneId || nextZoneId === profile.activeZoneId) {
      return;
    }
    const updated = characterService.updateMockProfile({ activeZoneId: nextZoneId });
    setProfile(updated);
    const zoneName = getZoneById(nextZoneId)?.name || 'New zone';
    toast.success(`${zoneName} is now active.`);
  };

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-6xl px-6 py-16 pt-24">
        <div className="mb-10 grid gap-6 lg:grid-cols-[1.35fr_0.65fr]">
          <div className="rounded-2xl p-8 shadow-2xl backdrop-blur court-reveal glass-panel">
            <div className="flex flex-wrap items-center justify-between gap-4">
              <div className="flex flex-wrap items-center gap-4">
                <div className="h-20 w-20 overflow-hidden rounded-2xl border border-yellow-700/40 bg-gray-900/70">
                  <img
                    src={character?.avatarUrl || '/raceicon/noimage.jpg'}
                    alt={character?.name || 'Unknown adventurer'}
                    className="h-full w-full object-cover"
                  />
                </div>
                <div>
                  <p className="section-kicker text-sm uppercase tracking-[0.3em] text-yellow-500">
                    Command Deck
                  </p>
                  <h1 className="mt-3 text-4xl font-extrabold text-white sm:text-5xl hero-title">
                    {character?.name || 'Unbound Wanderer'}
                  </h1>
                  <p className="mt-2 text-sm text-gray-300">
                    {character?.race || 'Unknown'} · {character?.className || 'Adventurer'}
                  </p>
                </div>
              </div>
              <div className="rounded-xl border border-yellow-700/30 bg-gray-950/70 px-4 py-3 text-center">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Level</p>
                <p className="mt-1 text-3xl font-semibold text-yellow-300">{playerLevel}</p>
              </div>
            </div>
            <div className="mt-6 overflow-hidden rounded-2xl border border-yellow-700/30 bg-gray-950/70">
              <img
                src="/banner.jpg"
                alt="Dashboard banner"
                className="h-44 w-full object-cover sm:h-56"
              />
            </div>
            <div className="mt-6 grid gap-4 lg:grid-cols-[1.1fr_0.9fr]">
              <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-5">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Character XP</p>
                <div className="mt-3">
                  <XpBar current={playerXp} target={playerXpTarget} label="Character XP" tone="gold" />
                </div>
                <div className="mt-4 flex flex-wrap items-center gap-3 text-xs text-gray-400">
                  <span className="inline-flex items-center gap-1 rounded-full border border-yellow-700/40 bg-yellow-500/10 px-3 py-1 text-yellow-200">
                    <svg
                      viewBox="0 0 24 24"
                      className="h-4 w-4"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      aria-hidden="true"
                    >
                      <ellipse cx="12" cy="7" rx="7" ry="3" />
                      <path d="M5 7v4c0 1.7 3.1 3 7 3s7-1.3 7-3V7" />
                      <path d="M5 11v4c0 1.7 3.1 3 7 3s7-1.3 7-3v-4" />
                    </svg>
                    <span>Gold: {profile?.stats?.gold ?? 0}</span>
                  </span>
                  <span className="rounded-full border border-yellow-700/40 bg-gray-900/80 px-3 py-1">
                    Residence: {activeHouse?.name || 'Starter Cottage'}
                  </span>
                  <span className="rounded-full border border-yellow-700/40 bg-gray-900/80 px-3 py-1">
                    Buff: {activeHouse?.effect?.name || 'Rested Comfort'}
                  </span>
                </div>
              </div>
              <div className="rounded-2xl border border-yellow-700/30 bg-gradient-to-br from-yellow-500/10 via-gray-950/80 to-gray-950/40 p-5">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Expedition Status</p>
                <p className="mt-2 text-xl font-semibold text-white">
                  {expeditionLocation ? expeditionLocation.name : 'No expedition'}
                </p>
                <p className="mt-1 text-sm text-gray-300">
                  {expeditionLocation?.summary || 'Deploy a crew to start earning rewards.'}
                </p>
                <div className="mt-4 flex flex-wrap items-center gap-2 text-xs text-gray-400">
                  <span>{expeditionLocation?.region || '—'}</span>
                  <span>·</span>
                  <span>{expeditionLocation?.biome || '—'}</span>
                </div>
                <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
                  <p className="text-xs text-gray-400">
                    {expeditionLocation
                      ? expeditionReady
                        ? 'Ready to claim rewards.'
                        : `Time left: ${formatDuration(expeditionRemaining)}`
                      : 'No active expedition.'}
                  </p>
                  <Link
                    to={expeditionLocation ? '/expedition-active' : '/adventure'}
                    className="rounded-lg px-3 py-2 text-xs font-semibold text-white action-primary"
                  >
                    {expeditionLocation ? 'View Expedition' : 'Start Expedition'}
                  </Link>
                </div>
              </div>
            </div>
          </div>
          <div className="rounded-2xl p-6 shadow-xl backdrop-blur court-reveal court-reveal-delay-1 court-card">
            <p className="text-xs uppercase tracking-[0.3em] text-yellow-500">Missions Spotlight</p>
            <h2 className="mt-3 text-2xl font-semibold text-white">Your General Missions</h2>
            <p className="mt-2 text-sm text-gray-300">
              Track progression goals and claim rewards as you level up.
            </p>
            <div className="mt-4 space-y-3">
              {missionSpotlight.length === 0 ? (
                <div className="rounded-xl border border-yellow-700/30 bg-gray-900/80 p-3 text-sm text-gray-300">
                  Missions will appear once you start leveling up.
                </div>
              ) : (
                missionSpotlight.map((mission) => (
                  <div
                    key={mission.id}
                    className="rounded-xl border border-yellow-700/30 bg-gray-900/80 p-3"
                  >
                    <div className="flex items-center justify-between text-sm text-gray-200">
                      <span>{mission.label}</span>
                      <span className="text-yellow-300">{mission.percent}%</span>
                    </div>
                    <div className="mt-2 h-2 rounded-full bg-gray-800">
                      <div
