}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import Sidebar from '../components/Sidebar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import { ensureFarmTasks, ensureFarmWeather, farmCrops, farmGoods } from '../data/farmData';
import { getSeedItemId } from '../data/itemsCatalog';
import { getItemCount } from '../services/inventoryService';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

export default function Farm() {
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    if (!MOCK_AUTH) {
      return;
    }

    sessionStorage.setItem('farmTasksAccess', 'true');
    const username = authService.getCurrentUsername();
    const nextProfile = characterService.getMockProfile(username);
    const { nextTasks, changed: tasksChanged } = ensureFarmTasks({
      tasks: nextProfile?.farmTasks,
      farmLevel: nextProfile?.farmLevel ?? 1,
    });
    const { nextWeather, changed: weatherChanged } = ensureFarmWeather({
      weather: nextProfile?.farmWeather,
    });

    if (tasksChanged || weatherChanged) {
      const updated = characterService.updateMockProfile({
        farmTasks: nextTasks,
        farmWeather: nextWeather,
      });
      setProfile(updated);
    } else {
      setProfile(nextProfile);
    }
  }, []);

  const inventory = profile?.inventory || {};

  const seedCount = useMemo(
    () => farmCrops.reduce((sum, crop) => sum + getItemCount(inventory, getSeedItemId(crop.id)), 0),
    [inventory]
  );

  const animalCount = useMemo(() => {
    const animals = profile?.farmAnimals || {};
    return Object.values(animals).reduce((sum, entry) => sum + (entry?.count || 0), 0);
  }, [profile]);

  const goodsCount = useMemo(
    () => farmGoods.reduce((sum, good) => sum + getItemCount(inventory, good.id), 0),
    [inventory]
  );

  const farmLevel = profile?.farmLevel ?? 1;
  const farmWeather = profile?.farmWeather;
  const dailyDone = (profile?.farmTasks?.daily?.tasks || []).filter((task) => task.claimed).length;
  const dailyTotal = profile?.farmTasks?.daily?.tasks?.length || 0;
  const weeklyDone = (profile?.farmTasks?.weekly?.tasks || []).filter((task) => task.claimed).length;
  const weeklyTotal = profile?.farmTasks?.weekly?.tasks?.length || 0;
  const monthlyDone = (profile?.farmTasks?.monthly?.tasks || []).filter((task) => task.claimed).length;
  const monthlyTotal = profile?.farmTasks?.monthly?.tasks?.length || 0;

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm2.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-4xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Harvestlands</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Farmstead</h1>
              <p className="mt-3 text-base text-gray-300">
                Manage plots, collect animal goods, and sell your harvest.
              </p>
              <p className="mt-3 text-sm text-yellow-200">Farm level: {farmLevel}</p>
            </div>
            <Link
              to="/dashboard"
              className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
            >
              Back to Dashboard
            </Link>
          </div>

          <div className="mt-6 overflow-hidden rounded-2xl border border-yellow-700/30 bg-gray-950/70">
            <img
              src="/farm.png"
              alt="Farmstead"
              className="h-48 w-full object-cover sm:h-56"
            />
          </div>

          {farmWeather && (
            <div className="mt-4 rounded-2xl border border-yellow-700/20 bg-gray-950/70 p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Today</p>
              <p className="mt-2 text-sm font-semibold text-white">
                {farmWeather.label} · {farmWeather.season}
              </p>
              <p className="mt-1 text-xs text-gray-400">
                Grow time x{farmWeather.growMultiplier} · Yield x{farmWeather.yieldMultiplier}
              </p>
            </div>
          )}

          <div className="mt-8 grid gap-4 sm:grid-cols-2">
            <Link
              to="/farm/plots"
              className="hint-wrap farm-hub-card farm-hub-card--plots rounded-2xl p-5"
            >
              <span className="mt-3 inline-flex rounded-full bg-yellow-500/10 px-3 py-1 text-xs text-yellow-200">
                Seeds owned: {seedCount}
              </span>
            </Link>
            <Link
              to="/farm/animals"
              className="hint-wrap farm-hub-card farm-hub-card--animals rounded-2xl p-5"
            >
              <span className="mt-3 inline-flex rounded-full bg-yellow-500/10 px-3 py-1 text-xs text-yellow-200">
                Animals owned: {animalCount}
              </span>
            </Link>
            <Link
              to="/market"
              className="hint-wrap farm-hub-card farm-hub-card--market rounded-2xl p-5"
            >
              <span className="mt-3 inline-flex rounded-full bg-yellow-500/10 px-3 py-1 text-xs text-yellow-200">
                Goods stored: {goodsCount}
              </span>
            </Link>
            <Link
              to="/farm/tasks"
              className="hint-wrap farm-hub-card farm-hub-card--tasks rounded-2xl p-5"
              onClick={() => sessionStorage.setItem('farmTasksAccess', 'true')}
            >
              <span className="mt-3 inline-flex flex-wrap gap-2 text-xs text-yellow-200">
                <span className="rounded-full bg-yellow-500/10 px-3 py-1">Daily {dailyDone}/{dailyTotal}</span>
                <span className="rounded-full bg-yellow-500/10 px-3 py-1">Weekly {weeklyDone}/{weeklyTotal}</span>
                <span className="rounded-full bg-yellow-500/10 px-3 py-1">Monthly {monthlyDone}/{monthlyTotal}</span>
              </span>
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import Sidebar from '../components/Sidebar';
import XpBar from '../components/XpBar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import { ensureFarmTasks, farmGoods, getFarmXpForLevel } from '../data/farmData';
import { getItemCount, removeItems } from '../services/inventoryService';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

const getGoodName = (goodId) => farmGoods.find((good) => good.id === goodId)?.name || 'Goods';

export default function FarmTasks() {
  const [profile, setProfile] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!MOCK_AUTH) {
      return;
    }

    const canAccess = sessionStorage.getItem('farmTasksAccess') === 'true';
    if (!canAccess) {
      navigate('/farm', { replace: true });
      return;
    }

    const username = authService.getCurrentUsername();
    const nextProfile = characterService.getMockProfile(username);
    const { nextTasks, changed } = ensureFarmTasks({
      tasks: nextProfile?.farmTasks,
      farmLevel: nextProfile?.farmLevel ?? 1,
    });

    if (changed) {
      const updated = characterService.updateMockProfile({ farmTasks: nextTasks });
      setProfile(updated);
    } else {
      setProfile(nextProfile);
    }
  }, []);

  const farmLevel = profile?.farmLevel ?? 1;
  const farmXp = profile?.farmXp ?? 0;
  const gold = profile?.stats?.gold ?? 0;
  const inventory = profile?.inventory || {};
  const farmXpTarget = getFarmXpForLevel(farmLevel);

  const tasks = profile?.farmTasks || {};
  const dailyTasks = tasks.daily?.tasks || [];
  const weeklyTasks = tasks.weekly?.tasks || [];
  const monthlyTasks = tasks.monthly?.tasks || [];

  const totals = useMemo(() => {
    const countClaimed = (list) => list.filter((task) => task.claimed).length;
    return {
      daily: { done: countClaimed(dailyTasks), total: dailyTasks.length },
      weekly: { done: countClaimed(weeklyTasks), total: weeklyTasks.length },
      monthly: { done: countClaimed(monthlyTasks), total: monthlyTasks.length },
    };
  }, [dailyTasks, weeklyTasks, monthlyTasks]);

  const applyFarmXp = (xpGain) => {
    let nextLevel = farmLevel;
    let nextXp = farmXp + xpGain;
    let target = getFarmXpForLevel(nextLevel);
    let leveledUp = false;

    while (nextXp >= target) {
      nextXp -= target;
      nextLevel += 1;
      target = getFarmXpForLevel(nextLevel);
      leveledUp = true;
    }

    return { nextLevel, nextXp, leveledUp };
  };

  const handleDeliver = (period, taskId) => {
    if (!MOCK_AUTH || !profile) {
      return;
    }

    const currentTasks = tasks[period]?.tasks || [];
    const taskIndex = currentTasks.findIndex((task) => task.id === taskId);
    if (taskIndex === -1) {
      return;
    }

    const task = currentTasks[taskIndex];
    if (task.claimed) {
      toast('Task already complete.', { icon: '✅' });
      return;
    }

    const owned = getItemCount(inventory, task.goodId);
    const remaining = Math.max(0, task.target - task.progress);
    const deliverAmount = Math.min(owned, remaining);

    if (deliverAmount <= 0) {
      toast.error('Not enough goods to deliver.');
      return;
    }

    const nextInventory = removeItems(inventory, { [task.goodId]: deliverAmount });

    const nextTasks = { ...tasks };
    const updatedTask = {
      ...task,
      progress: task.progress + deliverAmount,
    };

    if (updatedTask.progress >= updatedTask.target) {
      updatedTask.completed = true;
      updatedTask.claimed = true;
    }

    const periodTasks = [...currentTasks];
    periodTasks[taskIndex] = updatedTask;
    nextTasks[period] = { ...tasks[period], tasks: periodTasks };

    let nextStats = profile.stats;
    let nextFarmLevel = farmLevel;
    let nextFarmXp = farmXp;

    if (updatedTask.claimed) {
      const { nextLevel, nextXp, leveledUp } = applyFarmXp(updatedTask.rewardXp);
      nextFarmLevel = nextLevel;
      nextFarmXp = nextXp;
      nextStats = {
        ...profile.stats,
        gold: gold + updatedTask.rewardGold,
      };
      toast.success(
        `Delivered ${updatedTask.target} ${getGoodName(updatedTask.goodId)} · +${updatedTask.rewardGold}g${
          leveledUp ? ' · Farm level up!' : ''
        }`
      );
    } else {
      toast.success(`Delivered ${deliverAmount} ${getGoodName(updatedTask.goodId)}.`);
    }

    const updated = characterService.updateMockProfile({
      inventory: nextInventory,
      farmTasks: nextTasks,
      farmLevel: nextFarmLevel,
      farmXp: nextFarmXp,
      stats: nextStats,
    });

    setProfile(updated);
  };

  const renderTaskGroup = (label, periodKey, list, summary) => (
    <div className="rounded-2xl border border-yellow-700/20 bg-gray-950/70 p-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-xs uppercase tracking-[0.3em] text-gray-400">{label}</p>
          <p className="mt-2 text-sm text-gray-300">{summary.done}/{summary.total} complete</p>
        </div>
      </div>
      <div className="mt-4 space-y-3">
        {list.map((task) => {
          const owned = getItemCount(inventory, task.goodId);
          const remaining = Math.max(0, task.target - task.progress);
          const canDeliver = owned > 0 && !task.claimed;
          return (
            <div
              key={task.id}
              className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-3"
            >
              <div>
                <p className="text-sm font-semibold text-white">{task.label}</p>
                <p className="mt-1 text-xs text-gray-400">
                  Delivered {task.progress}/{task.target} · Owned {owned}
                </p>
                <p className="mt-1 text-xs text-gray-400">
                  Rewards: +{task.rewardXp} XP · +{task.rewardGold}g
                </p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => handleDeliver(periodKey, task.id)}
                  className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                    task.claimed
                      ? 'bg-gray-700 text-gray-300'
                      : canDeliver
                      ? 'action-primary text-white'
                      : 'bg-gray-700 text-gray-300'
                  }`}
                  disabled={!canDeliver}
                >
                  {task.claimed ? 'Complete' : remaining === 0 ? 'Complete' : 'Deliver'}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  if (!MOCK_AUTH) {
    return (
      <div className="min-h-screen bg-gray-900 text-gray-200 flex items-center justify-center p-6">
        Farm tasks are available only in offline mode.
      </div>
    );
  }

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm2.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Harvestlands</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Farm Tasks</h1>
              <p className="mt-3 text-base text-gray-300">
                Deliver goods from your inventory to earn farm XP and gold.
              </p>
            </div>
            <Link
              to="/farm"
              onClick={() => sessionStorage.setItem('farmTasksAccess', 'true')}
              className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
            >
              Back to Farm
            </Link>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Farm Level</p>
              <p className="mt-2 text-2xl font-semibold text-white">{farmLevel}</p>
              <div className="mt-3">
                <XpBar current={farmXp} target={farmXpTarget} label="Farm XP" tone="emerald" />
              </div>
            </div>
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Gold</p>
              <p className="mt-2 text-2xl font-semibold text-yellow-300">{gold}</p>
            </div>
            <div className="image-panel image-panel-housing ornament-frame p-4">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Inventory</p>
                <p className="mt-2 text-2xl font-semibold text-white">
                  {farmGoods.reduce((sum, good) => sum + getItemCount(inventory, good.id), 0)} goods
                </p>
              </div>
            </div>
          </div>

          <div className="mt-8 space-y-6">
            {renderTaskGroup('Daily Orders', 'daily', dailyTasks, totals.daily)}
            {renderTaskGroup('Weekly Orders', 'weekly', weeklyTasks, totals.weekly)}
            {renderTaskGroup('Monthly Orders', 'monthly', monthlyTasks, totals.monthly)}
          </div>
        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import Sidebar from '../components/Sidebar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import { getItemById } from '../data/itemsCatalog';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

const rarityRank = {
  Common: 1,
  Uncommon: 2,
  Rare: 3,
  Epic: 4,
  Legendary: 5,
  Mythic: 6,
  Relic: 7,
};

const rarityStyles = {
  Common: 'border-gray-500/50 text-gray-300',
  Uncommon: 'border-emerald-400/50 text-emerald-200',
  Rare: 'border-sky-400/50 text-sky-200',
  Epic: 'border-fuchsia-400/50 text-fuchsia-200',
  Legendary: 'border-amber-400/50 text-amber-200',
  Mythic: 'border-rose-400/50 text-rose-200',
  Relic: 'border-yellow-400/50 text-yellow-200',
};

const getItemValue = (item) => item?.sellPrice ?? item?.price ?? item?.estimate ?? 0;

export default function Inventory() {
  const [profile, setProfile] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [typeFilter, setTypeFilter] = useState('All');
  const [sortBy, setSortBy] = useState('name');

  useEffect(() => {
    if (!MOCK_AUTH) {
      return;
    }

    const username = authService.getCurrentUsername();
    const nextProfile = characterService.getMockProfile(username);
    setProfile(nextProfile);
  }, []);

  const inventory = profile?.inventory || {};
  const inventoryRows = useMemo(() => {
    return Object.entries(inventory)
      .map(([itemId, amount]) => {
        const item = getItemById(itemId);
        if (!item) {
          return null;
        }
        return {
          ...item,
          amount,
          value: getItemValue(item),
          rarityRank: rarityRank[item.rarity] || 0,
        };
      })
      .filter(Boolean);
  }, [inventory]);

  const categories = useMemo(() => {
    const unique = new Set(inventoryRows.map((item) => item.category || 'Misc'));
    return ['All', ...Array.from(unique)];
  }, [inventoryRows]);

  const types = useMemo(() => {
    const unique = new Set(inventoryRows.map((item) => item.type || 'misc'));
    return ['All', ...Array.from(unique)];
  }, [inventoryRows]);

  const normalizedSearch = searchTerm.trim().toLowerCase();
  const filteredRows = useMemo(() => {
    return inventoryRows.filter((item) => {
      const matchesSearch = !normalizedSearch || item.name.toLowerCase().includes(normalizedSearch);
      const matchesCategory = categoryFilter === 'All' || item.category === categoryFilter;
      const matchesType = typeFilter === 'All' || item.type === typeFilter;
      return matchesSearch && matchesCategory && matchesType;
    });
  }, [inventoryRows, normalizedSearch, categoryFilter, typeFilter]);

  const sortedRows = useMemo(() => {
    const rows = [...filteredRows];
    rows.sort((a, b) => {
      if (sortBy === 'quantity') return (b.amount || 0) - (a.amount || 0);
      if (sortBy === 'value') return (b.value || 0) - (a.value || 0);
      if (sortBy === 'rarity') return (b.rarityRank || 0) - (a.rarityRank || 0);
      return a.name.localeCompare(b.name);
    });
    return rows;
  }, [filteredRows, sortBy]);

  const totalItems = sortedRows.reduce((sum, item) => sum + (item.amount || 0), 0);
  const debugCounts = useMemo(() => {
    const byType = {};
    const byCategory = {};

    inventoryRows.forEach((item) => {
      const type = item.type || 'misc';
      const category = item.category || 'Misc';
      byType[type] = (byType[type] || 0) + (item.amount || 0);
      byCategory[category] = (byCategory[category] || 0) + (item.amount || 0);
    });

    return {
      byType,
      byCategory,
    };
  }, [inventoryRows]);

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-6xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-6 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Vault Ledger</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Inventory</h1>
              <p className="mt-3 text-base text-gray-300">
                One global vault for ores, harvests, crafted wares, and relic gear.
              </p>
            </div>
            <div className="flex flex-wrap gap-2 text-xs text-gray-300">
              <span className="court-chip rounded-full px-3 py-1">Unique: {sortedRows.length}</span>
              <span className="court-chip rounded-full px-3 py-1">Total: {totalItems}</span>
            </div>
          </div>

          <div className="mt-6 grid gap-4 lg:grid-cols-[1.1fr_0.9fr]">
            <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Filters</p>
              <div className="mt-3 grid gap-3 sm:grid-cols-2">
                <label className="text-xs text-gray-300">
                  Search
                  <input
                    type="search"
                    value={searchTerm}
                    onChange={(event) => setSearchTerm(event.target.value)}
                    placeholder="Item name"
                    className="mt-2 w-full rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  />
                </label>
                <label className="text-xs text-gray-300">
                  Category
                  <select
                    value={categoryFilter}
                    onChange={(event) => setCategoryFilter(event.target.value)}
                    className="mt-2 w-full rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  >
                    {categories.map((category) => (
                      <option key={category} value={category} className="text-gray-900">
                        {category}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-300">
                  Type
                  <select
                    value={typeFilter}
                    onChange={(event) => setTypeFilter(event.target.value)}
                    className="mt-2 w-full rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  >
                    {types.map((type) => (
                      <option key={type} value={type} className="text-gray-900">
                        {type}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-300">
                  Sort
                  <select
                    value={sortBy}
                    onChange={(event) => setSortBy(event.target.value)}
                    className="mt-2 w-full rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  >
                    <option value="name" className="text-gray-900">Name</option>
                    <option value="quantity" className="text-gray-900">Quantity</option>
                    <option value="value" className="text-gray-900">Value</option>
                    <option value="rarity" className="text-gray-900">Rarity</option>
                  </select>
                </label>
              </div>
              <details className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 px-3 py-2 text-xs text-gray-300">
                <summary className="cursor-pointer text-yellow-200">Inventory debug</summary>
                <div className="mt-3 grid gap-3 sm:grid-cols-2">
                  <div>
                    <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400">By Type</p>
                    <div className="mt-2 space-y-1">
                      {Object.entries(debugCounts.byType).map(([type, amount]) => (
                        <div key={type} className="flex items-center justify-between">
                          <span>{type}</span>
                          <span className="text-yellow-200">{amount}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div>
                    <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400">By Category</p>
                    <div className="mt-2 space-y-1">
                      {Object.entries(debugCounts.byCategory).map(([category, amount]) => (
                        <div key={category} className="flex items-center justify-between">
                          <span>{category}</span>
                          <span className="text-yellow-200">{amount}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </details>
            </div>

            <div className="image-panel image-panel-inventory ornament-frame p-4">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-yellow-300">Catalog</p>
                <p className="mt-2 text-lg font-semibold text-white">Unified Inventory</p>
                <p className="mt-2 text-sm text-gray-300">
                  Every system deposits here. Crafted items, crops, ores, and relics now share one vault.
                </p>
              </div>
            </div>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-2">
            {sortedRows.length === 0 ? (
              <div className="rounded-xl border border-yellow-700/20 bg-gray-950/70 p-6 text-sm text-gray-300">
                Inventory is empty. Mine, farm, or craft to stock the vault.
              </div>
            ) : (
              sortedRows.map((item) => (
                <div
                  key={item.id}
                  className="court-card rounded-xl p-4 hover-lift"
                  title={`${item.name} · ${item.category || 'Misc'}`}
                >
                  <div className="flex items-start gap-4">
                    <div className="h-16 w-16 overflow-hidden rounded-xl border border-yellow-700/30 bg-gray-950/70">
                      <img
                        src={item.image || '/raceicon/noimage.jpg'}
                        alt={item.name}
                        className="h-full w-full object-cover"
                        onError={(event) => {
                          event.target.onerror = null;
                          event.target.src = '/raceicon/noimage.jpg';
                        }}
                      />
                    </div>
                    <div className="flex-1">
                      <div className="flex flex-wrap items-center justify-between gap-2">
                        <h2 className="text-xl font-semibold text-white">{item.name}</h2>
                        <span className="rounded-full bg-yellow-500/10 px-3 py-1 text-xs text-yellow-200">
                          x{item.amount}
                        </span>
                      </div>
                      <div className="mt-2 flex flex-wrap items-center gap-2 text-xs text-gray-300">
                        <span className="rounded-full border border-yellow-700/30 px-3 py-1">
                          {item.category || 'Misc'}
                        </span>
                        <span className="rounded-full border border-yellow-700/30 px-3 py-1">
                          {item.type || 'misc'}
                        </span>
                        {item.rarity && (
                          <span
                            className={`rounded-full border px-3 py-1 ${
                              rarityStyles[item.rarity] || rarityStyles.Common
                            }`}
                          >
                            {item.rarity}
                          </span>
                        )}
                      </div>
                      {item.description && (
                        <p className="mt-2 text-sm text-gray-300">{item.description}</p>
                      )}
                      <p className="mt-2 text-xs text-gray-400">Value: {item.value}g</p>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          <Link
            to="/dashboard"
            className="mt-8 inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold text-yellow-200 action-ghost"
          >
            Back to Dashboard
          </Link>
        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import Sidebar from '../components/Sidebar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import { itemsCatalog } from '../data/itemsCatalog';
import { addItems, getItemCount, removeItems } from '../services/inventoryService';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

const rarityRank = {
  Common: 1,
  Uncommon: 2,
  Rare: 3,
  Epic: 4,
  Legendary: 5,
  Mythic: 6,
  Relic: 7,
};

const marketFilters = [
  { id: 'all', label: 'All', predicate: () => true },
  { id: 'seeds', label: 'Seeds', predicate: (item) => item.type === 'seed' },
  { id: 'farm-goods', label: 'Farm Goods', predicate: (item) => item.type === 'farm-good' },
  { id: 'farm-animals', label: 'Farm Animals', predicate: (item) => item.type === 'farm-animal' },
  { id: 'ore', label: 'Ores', predicate: (item) => item.type === 'ore' },
  { id: 'consumables', label: 'Consumables', predicate: (item) => item.type === 'consumable' },
  { id: 'crafted', label: 'Crafted', predicate: (item) => item.type === 'crafted' },
  { id: 'gear', label: 'Gear', predicate: (item) => item.type === 'gear' },
  { id: 'tokens', label: 'Tokens', predicate: (item) => item.type === 'token' },
  {
    id: 'rare',
    label: 'Rare+',
    predicate: (item) => (rarityRank[item.rarity] || 0) >= 3,
  },
];

const groupedFilters = marketFilters.filter((filter) => !['all', 'rare'].includes(filter.id));
const COLLAPSED_SECTIONS_KEY = 'marketCollapsedSections';
const BULK_SELL_CONFIRM_KEY = 'marketBulkSellConfirmDisabled';

const getBuyPrice = (item) => {
  if (!item) {
    return 0;
  }
  return (
    item.buyPrice ??
    item.price ??
    item.estimate ??
    (item.sellPrice ? Math.round(item.sellPrice * 1.3) : 0)
  );
};

const getSellPrice = (item) => {
  if (!item) {
    return 0;
  }
  if (item.sellPrice != null) {
    return item.sellPrice;
  }
  if (item.price != null) {
    return Math.round(item.price * 0.6);
  }
  if (item.estimate != null) {
    return Math.round(item.estimate * 0.6);
  }
  return 0;
};

const formatGold = (value) => new Intl.NumberFormat('en-US').format(value || 0);

export default function Market() {
  const [profile, setProfile] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterId, setFilterId] = useState('all');
  const [sortBy, setSortBy] = useState('name');
  const [quantities, setQuantities] = useState({});
  const [collapsedSections, setCollapsedSections] = useState({});
  const [showOwnedOnly, setShowOwnedOnly] = useState(false);
  const [pendingBulkSale, setPendingBulkSale] = useState(null);
  const [skipBulkConfirm, setSkipBulkConfirm] = useState(false);

  useEffect(() => {
    if (!MOCK_AUTH) {
      return;
    }

    const username = authService.getCurrentUsername();
    const nextProfile = characterService.getMockProfile(username);
    setProfile(nextProfile);
  }, []);

  useEffect(() => {
    const stored = localStorage.getItem(COLLAPSED_SECTIONS_KEY);
    if (!stored) {
      return;
    }
    try {
      const parsed = JSON.parse(stored);
      if (parsed && typeof parsed === 'object') {
        setCollapsedSections(parsed);
      }
    } catch {
      localStorage.removeItem(COLLAPSED_SECTIONS_KEY);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(COLLAPSED_SECTIONS_KEY, JSON.stringify(collapsedSections));
  }, [collapsedSections]);

  useEffect(() => {
    const stored = localStorage.getItem(BULK_SELL_CONFIRM_KEY);
    setSkipBulkConfirm(stored === 'true');
  }, []);

  useEffect(() => {
    localStorage.setItem(BULK_SELL_CONFIRM_KEY, skipBulkConfirm ? 'true' : 'false');
  }, [skipBulkConfirm]);

  const inventory = profile?.inventory || {};
  const farmAnimalsOwned = profile?.farmAnimals || {};
  const gold = profile?.stats?.gold ?? 0;

  const marketItems = useMemo(() => {
    return itemsCatalog.map((item, index) => {
      const buyPrice = getBuyPrice(item);
      const sellPrice = getSellPrice(item);
      return {
        ...item,
        index,
        buyPrice,
        sellPrice,
        buyable: buyPrice > 0,
        sellable: sellPrice > 0,
        owned: item.type === 'farm-animal'
          ? farmAnimalsOwned[item.id]?.count || 0
          : getItemCount(inventory, item.id),
        rarityRank: rarityRank[item.rarity] || 0,
      };
    });
  }, [inventory, farmAnimalsOwned]);

  const normalizedSearch = searchTerm.trim().toLowerCase();
  const filteredItems = useMemo(() => {
    const activeFilter = marketFilters.find((filter) => filter.id === filterId) || marketFilters[0];
    return marketItems.filter((item) => {
      const matchesFilter = activeFilter.predicate(item);
      const matchesSearch =
        !normalizedSearch ||
        item.name.toLowerCase().includes(normalizedSearch) ||
        (item.category || '').toLowerCase().includes(normalizedSearch);
      const matchesOwned = !showOwnedOnly || item.owned > 0;
      return matchesFilter && matchesSearch && matchesOwned;
    });
  }, [marketItems, filterId, normalizedSearch, showOwnedOnly]);

  const sortedItems = useMemo(() => {
    const rows = [...filteredItems];
    rows.sort((a, b) => {
      if (sortBy === 'buy') return b.buyPrice - a.buyPrice || a.index - b.index;
      if (sortBy === 'sell') return b.sellPrice - a.sellPrice || a.index - b.index;
      if (sortBy === 'category') return (a.category || '').localeCompare(b.category || '') || a.index - b.index;
      if (sortBy === 'rarity') return b.rarityRank - a.rarityRank || a.index - b.index;
      return a.name.localeCompare(b.name) || a.index - b.index;
    });
    return rows;
  }, [filteredItems, sortBy]);

  const filterCounts = useMemo(() => {
    const counts = {};
    marketFilters.forEach((filter) => {
      counts[filter.id] = marketItems.filter((item) => filter.predicate(item)).length;
    });
    return counts;
  }, [marketItems]);

  const groupedSections = useMemo(() => {
    if (filterId !== 'all') {
      return [];
    }

    return groupedFilters
      .map((filter) => {
        const items = sortedItems.filter((item) => filter.predicate(item));
        return {
          id: filter.id,
          label: filter.label,
          items,
        };
      })
      .filter((section) => section.items.length > 0);
  }, [filterId, sortedItems]);

  const sellAllGoods = useMemo(() => {
    const items = marketItems.filter((item) => item.type === 'farm-good' && item.sellable && item.owned > 0);
    const itemMap = {};
    let totalValue = 0;
    let totalCount = 0;
    items.forEach((item) => {
      itemMap[item.id] = item.owned;
      totalCount += item.owned;
      totalValue += item.sellPrice * item.owned;
    });
    return { itemMap, totalCount, totalValue };
  }, [marketItems]);

  const sellAllOres = useMemo(() => {
    const items = marketItems.filter((item) => item.type === 'ore' && item.sellable && item.owned > 0);
    const itemMap = {};
    let totalValue = 0;
    let totalCount = 0;
    items.forEach((item) => {
      itemMap[item.id] = item.owned;
      totalCount += item.owned;
      totalValue += item.sellPrice * item.owned;
    });
    return { itemMap, totalCount, totalValue };
  }, [marketItems]);

  const allSectionsCollapsed = groupedSections.length > 0
    && groupedSections.every((section) => collapsedSections[section.id]);

  const handleToggleAllSections = () => {
    if (groupedSections.length === 0) {
      return;
    }

    if (allSectionsCollapsed) {
      setCollapsedSections({});
      return;
    }

    const next = {};
    groupedSections.forEach((section) => {
      next[section.id] = true;
    });
    setCollapsedSections(next);
  };

  const handleToggleSection = (sectionId) => {
    setCollapsedSections((prev) => ({
      ...prev,
      [sectionId]: !prev[sectionId],
    }));
  };

  const handleQuantityChange = (itemId, value) => {
    const next = Math.max(1, Number.parseInt(value, 10) || 1);
    setQuantities((prev) => ({ ...prev, [itemId]: next }));
  };

  const handleBuy = (item) => {
    if (!MOCK_AUTH || !profile) {
      return;
    }
    if (!item.buyable) {
      toast.error('This item is not for sale.');
      return;
    }
    const quantity = Math.max(1, quantities[item.id] || 1);
    const totalCost = item.buyPrice * quantity;

    if (gold < totalCost) {
      toast.error('Not enough gold for that purchase.');
      return;
    }

    let updated;
    if (item.type === 'farm-animal') {
      const current = farmAnimalsOwned[item.id] || { count: 0, lastCollectedAt: 0 };
      const nextAnimals = {
        ...farmAnimalsOwned,
        [item.id]: {
          count: current.count + quantity,
          lastCollectedAt: current.lastCollectedAt || Date.now(),
        },
      };
      updated = characterService.updateMockProfile({
        farmAnimals: nextAnimals,
        stats: {
          ...profile.stats,
          gold: gold - totalCost,
        },
      });
    } else {
      const nextInventory = addItems(inventory, { [item.id]: quantity });
      updated = characterService.updateMockProfile({
        inventory: nextInventory,
        stats: {
          ...profile.stats,
          gold: gold - totalCost,
        },
      });
    }

    setProfile(updated);
    toast.success(`Bought ${quantity} ${item.name}.`);
  };

  const handleSell = (item) => {
    if (!MOCK_AUTH || !profile) {
      return;
    }
    if (!item.sellable) {
      toast.error('This item cannot be sold.');
      return;
    }
    const owned = item.type === 'farm-animal'
      ? farmAnimalsOwned[item.id]?.count || 0
      : getItemCount(inventory, item.id);
    if (owned <= 0) {
      toast.error('No items to sell.');
      return;
    }
    const quantity = Math.min(owned, Math.max(1, quantities[item.id] || 1));
    const totalValue = item.sellPrice * quantity;

    let updated;
    if (item.type === 'farm-animal') {
      const current = farmAnimalsOwned[item.id] || { count: 0, lastCollectedAt: 0 };
      const nextCount = Math.max(0, current.count - quantity);
      const nextAnimals = { ...farmAnimalsOwned };
      if (nextCount > 0) {
        nextAnimals[item.id] = { count: nextCount, lastCollectedAt: current.lastCollectedAt };
      } else {
        delete nextAnimals[item.id];
      }
      updated = characterService.updateMockProfile({
        farmAnimals: nextAnimals,
        stats: {
          ...profile.stats,
          gold: gold + totalValue,
        },
      });
    } else {
      const nextInventory = removeItems(inventory, { [item.id]: quantity });
      updated = characterService.updateMockProfile({
        inventory: nextInventory,
        stats: {
          ...profile.stats,
          gold: gold + totalValue,
        },
      });
    }

    setProfile(updated);
    toast.success(`Sold ${quantity} ${item.name}.`);
  };

  const handleSellAllGoods = () => {
    if (!MOCK_AUTH || !profile) {
      return;
    }
    if (sellAllGoods.totalCount <= 0) {
      toast.error('No farm goods to sell.');
      return;
    }
    if (skipBulkConfirm) {
      const updated = characterService.updateMockProfile({
        inventory: removeItems(inventory, sellAllGoods.itemMap),
        stats: {
          ...profile.stats,
          gold: gold + sellAllGoods.totalValue,
        },
      });

      setProfile(updated);
      toast.success(`Sold all farm goods for ${formatGold(sellAllGoods.totalValue)}g.`);
      return;
    }

    setPendingBulkSale({
      type: 'goods',
      label: 'farm goods',
      totalCount: sellAllGoods.totalCount,
      totalValue: sellAllGoods.totalValue,
      itemMap: sellAllGoods.itemMap,
    });
  };

  const handleSellAllOres = () => {
    if (!MOCK_AUTH || !profile) {
      return;
    }
    if (sellAllOres.totalCount <= 0) {
      toast.error('No ores to sell.');
      return;
    }
    if (skipBulkConfirm) {
      const updated = characterService.updateMockProfile({
        inventory: removeItems(inventory, sellAllOres.itemMap),
        stats: {
          ...profile.stats,
          gold: gold + sellAllOres.totalValue,
        },
      });

      setProfile(updated);
      toast.success(`Sold all ores for ${formatGold(sellAllOres.totalValue)}g.`);
      return;
    }

    setPendingBulkSale({
      type: 'ores',
      label: 'ores',
      totalCount: sellAllOres.totalCount,
      totalValue: sellAllOres.totalValue,
      itemMap: sellAllOres.itemMap,
    });
  };

  const handleConfirmBulkSale = () => {
    if (!MOCK_AUTH || !profile || !pendingBulkSale) {
      return;
    }

    const updated = characterService.updateMockProfile({
      inventory: removeItems(inventory, pendingBulkSale.itemMap),
      stats: {
        ...profile.stats,
        gold: gold + pendingBulkSale.totalValue,
      },
    });

    setProfile(updated);
    toast.success(`Sold all ${pendingBulkSale.label} for ${formatGold(pendingBulkSale.totalValue)}g.`);
    setPendingBulkSale(null);
  };

  const handleCancelBulkSale = () => {
    setPendingBulkSale(null);
  };

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-6xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">World Exchange</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Global Market</h1>
              <p className="mt-3 max-w-2xl text-base text-gray-300">
                One hub for trading every resource, relic, and crafted good across the realm.
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <div className="rounded-full border border-yellow-700/40 bg-gray-950/70 px-4 py-2 text-xs text-yellow-200">
                Gold: {formatGold(gold)}
              </div>
              <Link
                to="/inventory"
                className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
              >
                Open Inventory
              </Link>
            </div>
          </div>

          <div className="mt-8 rounded-2xl border border-yellow-700/30 bg-gray-900/80 p-6">
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <p className="text-xs uppercase tracking-[0.3em] text-yellow-500">Market Controls</p>
