      inventory: nextInventory,
      miningBoosterCooldowns: nextCooldowns,
      activeMiningBoost: nextActiveBoostId,
    });

    setProfile(updated);
  }, [
    now,
    profile,
    isMining,
    miningLevel,
    pickaxeLevel,
    inventory,
    boosterCooldowns,
    activeBoostId,
    hirelingTicksPerHour,
