      stats: {
        ...profile.stats,
        gold: gold - hireling.price,
      },
      miningHirelings: [...miningHirelingsOwned, hirelingId],
    });

    setProfile(updated);
    toast.success(`${hireling.name} hired.`);
  };

  const handleDismissHireling = (hirelingId) => {
