  }, [lastResult]);

  const currentHaulList = useMemo(() => {
    if (!miningSession?.accruedYield) {
      return [];
    }
    return Object.entries(miningSession.accruedYield).map(([oreId, amount]) => {
      const ore = miningOres.find((item) => item.id === oreId);
      return {
        id: oreId,
        name: ore?.name || oreId,
        amount,
      };
    });
  }, [miningSession]);

  const hirelingContribution = miningSession?.hirelingTicks
    ? Math.max(0, miningSession.hirelingTicks)
    : 0;

  const hirelingBreakdown = useMemo(() => {
    const map = miningSession?.hirelingTickMap || {};
    return Object.entries(map)
      .map(([id, count]) => ({
        id,
        count,
        name: miningHirelings.find((item) => item.id === id)?.name || id,
      }))
      .filter((entry) => entry.count > 0);
  }, [miningSession, miningHirelings]);

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Deepforge</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Mining Outpost</h1>
              <p className="mt-3 text-base text-gray-300">
                Enter the mines to gather ore. Stopping early applies a 4-hour cooldown.
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <Link
                to="/mining/click"
                className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
              >
                Mine by Clicking
              </Link>
              <Link
                to="/market"
                className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
              >
                Global Market
              </Link>
            </div>
          </div>

          <div className="mt-6 overflow-hidden rounded-2xl border border-yellow-700/30 bg-gray-950/70">
            <img
              src="/cave.png"
              alt="Mining cave"
              className="h-48 w-full object-cover sm:h-56"
            />
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Mining Level</p>
              <p className="mt-2 text-2xl font-semibold text-white">{miningLevel}</p>
              <div className="mt-3">
                <XpBar current={miningXp} target={xpToNext} label="Mining XP" tone="cyan" />
              </div>
              {hirelingBreakdown.length > 0 && (
                <details
                  className="mt-2 rounded-lg border border-yellow-700/20 bg-gray-950/70 px-3 py-2 text-xs text-gray-400"
                  open={miningHirelingsOwned.length > 0}
                >
                  <summary className="flex cursor-pointer items-center justify-between text-yellow-200">
                    <span>Hireling contributions</span>
                    <span className="text-[10px] text-yellow-200">▾</span>
                  </summary>
                  <div className="mt-2 space-y-1">
                    {hirelingBreakdown.map((entry) => (
                      <div key={entry.id} className="flex items-center justify-between">
                        <span>{entry.name}</span>
                        <span className="text-yellow-200">{entry.count} ticks</span>
                      </div>
                    ))}
                  </div>
                </details>
              )}
            </div>
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Pickaxe Level</p>
              <p className="mt-2 text-2xl font-semibold text-white">{pickaxeLevel}</p>
              <p className="mt-2 text-xs text-gray-400">
                {currentPickaxe?.name || 'Pickaxe'} | {currentPickaxe?.rarity || 'Common'}
              </p>
              {currentPickaxe?.visual && (
                <p className="mt-1 text-xs text-gray-500">{currentPickaxe.visual}</p>
              )}
            </div>
            <div className="image-panel image-panel-housing ornament-frame p-4">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Session</p>
                <p className="mt-2 text-2xl font-semibold text-white">
                  {isMining ? 'In Progress' : 'Idle'}
                </p>
                <p className="mt-2 text-sm text-gray-300">
                  {isMining
                    ? `Time left: ${formatDuration(remainingMs)}`
                    : isMiningCooldown
                      ? `Cooldown: ${formatDuration(miningCooldownRemaining)}`
                      : 'Start a new mining run.'}
                </p>
                <p className="mt-3 text-xs text-gray-400">Auto-claim active.</p>
                <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-black/50">
                  <div
                    className="h-full rounded-full bg-yellow-500/70 transition-all"
                    style={{ width: `${miningProgress}%` }}
                  />
                </div>
                {boosterCooldownRows.some((row) => row.isActive) ? (
                  <div className="mt-3 space-y-2 text-xs text-gray-300">
                    {boosterCooldownRows
                      .filter((row) => row.isActive)
                      .map((row) => (
                        <div key={row.booster.id}>
                          <p>
                            Booster cooldown: {row.booster.name} ({formatDuration(row.remaining)})
                          </p>
                          <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-black/50">
                            <div
                              className="h-full rounded-full bg-amber-400/70"
                              style={{ width: `${row.progress}%` }}
                            />
                          </div>
                        </div>
                      ))}
                  </div>
                ) : (
                  <p className="mt-3 text-xs text-gray-400">No booster cooldowns active.</p>
                )}
              </div>
            </div>
          </div>

          <div className="mt-6 flex flex-wrap gap-3">
            <button
              type="button"
              onClick={handleStartMining}
              disabled={isMining || isMiningCooldown}
              className={`inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold ${
                isMining || isMiningCooldown ? 'bg-gray-700 text-gray-300' : 'action-primary text-white'
              }`}
            >
              Start Mining
            </button>
            <button
              type="button"
              onClick={handleStopMining}
              disabled={!isMining}
              className={`inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold ${
                isMining ? 'border border-yellow-600/60 text-yellow-200' : 'bg-gray-700 text-gray-300'
              }`}
            >
              Stop Mining
            </button>
            <Link
              to="/dashboard"
              className="inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold text-yellow-200 action-ghost"
            >
              Back to Dashboard
            </Link>
          </div>

          <div className="mt-6 grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Current Haul</p>
              <p className="mt-2 text-sm text-gray-300">
                Ore mined so far. Claim any time while the timer runs.
              </p>
              <p className="mt-2 text-xs text-gray-400">Hireling ticks: {hirelingContribution}</p>
              {hirelingBreakdown.length > 0 && (
                <div className="mt-2 space-y-1 text-xs text-gray-400">
                  {hirelingBreakdown.map((entry) => (
                    <div key={entry.id} className="flex items-center justify-between">
                      <span>{entry.name}</span>
                      <span className="text-yellow-200">{entry.count} ticks</span>
                    </div>
                  ))}
                </div>
              )}
              {currentHaulList.length === 0 ? (
                <p className="mt-4 text-sm text-gray-400">No ore mined yet.</p>
              ) : (
                <ul className="mt-4 space-y-2 text-sm text-gray-300">
                  {currentHaulList.map((item) => (
                    <li key={item.id} className="flex items-center justify-between">
                      <span>{item.name}</span>
                      <span className="text-yellow-200">+{item.amount}</span>
                    </li>
                  ))}
                </ul>
              )}
            </div>
            <div className="image-panel image-panel-market ornament-frame p-6">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Accrued XP</p>
                <p className="mt-3 text-2xl font-semibold text-white">{accruedXp}</p>
                {miningSession?.accruedTicks ? (
                  <p className="mt-1 text-xs text-gray-400">Ticks mined: {miningSession.accruedTicks}</p>
                ) : null}
                <div className="mt-3 rounded-lg border border-yellow-700/20 bg-gray-950/60 px-3 py-2">
                  <p className="text-[10px] uppercase tracking-[0.3em] text-yellow-400">Events This Run</p>
                  <div className="mt-2 grid gap-1 text-xs text-gray-300">
                    <p>Rare Nodes: {eventCounts.rare || 0}</p>
                    <p>Critical Strikes: {eventCounts.crit || 0}</p>
                    <p>Mishaps: {eventCounts.mishap || 0}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="mt-8 grid gap-4 sm:grid-cols-2">
            <div className="image-panel image-panel-market ornament-frame p-5">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Pickaxe Portrait</p>
                <p className="mt-3 text-lg font-semibold text-white">
                  {currentPickaxe?.name || 'Pickaxe'}
                </p>
                <p className="mt-1 text-xs text-gray-400">
                  {currentPickaxe?.rarity || 'Common'} tier
                </p>
                {currentPickaxe?.visual && (
                  <p className="mt-2 text-xs text-gray-400">{currentPickaxe.visual}</p>
                )}
                <div className="mt-4 flex flex-wrap items-center gap-4">
                  {currentPickaxe?.image && (
                    <div className="rounded-xl border border-yellow-700/30 bg-gray-950/70 p-2">
                      <img
                        src={currentPickaxe.image}
                        alt={currentPickaxe.name}
                        className="h-20 w-20 object-contain"
                      />
                      <p className="mt-2 text-[10px] uppercase tracking-[0.3em] text-gray-400">Current</p>
                    </div>
                  )}
                  {nextPickaxe?.image && (
                    <div className="rounded-xl border border-yellow-700/30 bg-gray-950/70 p-2">
                      <img
                        src={nextPickaxe.image}
                        alt={nextPickaxe.name}
                        className="h-20 w-20 object-contain"
                      />
                      <p className="mt-2 text-[10px] uppercase tracking-[0.3em] text-gray-400">Next</p>
                    </div>
                  )}
                </div>
                <div className="mt-4 rounded-xl border border-yellow-700/30 bg-gray-950/70 p-4">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Pickaxe Upgrade</p>
                  {nextPickaxe ? (
                    <>
                      <p className="mt-2 text-sm font-semibold text-white">{nextPickaxe.name}</p>
                      <p className="mt-1 text-xs text-gray-400">
                        Requires mining level {nextPickaxe.requiredMiningLevel} · {nextPickaxe.price}g
                      </p>
                      <button
                        type="button"
                        onClick={handleUpgradePickaxe}
                        className={`mt-3 w-full rounded-lg px-3 py-2 text-xs font-semibold ${
                          miningLevel >= nextPickaxe.requiredMiningLevel && gold >= nextPickaxe.price
                            ? 'action-primary text-white'
                            : 'bg-gray-700 text-gray-300'
                        }`}
                        disabled={miningLevel < nextPickaxe.requiredMiningLevel || gold < nextPickaxe.price}
                      >
                        Upgrade Pickaxe
                      </button>
                    </>
                  ) : (
                    <p className="mt-2 text-xs text-gray-400">Pickaxe fully upgraded.</p>
                  )}
                </div>
              </div>
            </div>
            <div className="court-card rounded-xl p-5">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Mining Notes</p>
              <p className="mt-2 text-sm text-gray-300">
                Rare nodes and critical strikes can spike your haul. Mishaps can reduce a tick.
              </p>
              <div className="mt-3 space-y-1 text-xs text-gray-400">
                <p>
                  Daily Vein: +25% {miningOres.find((ore) => ore.id === dailyVeinBonus.oreId)?.name || 'ore'} yield
                </p>
                <p>Weekly Surge: +{Math.round((weeklySurgeBonus.xpMultiplier - 1) * 100)}% XP</p>
                <p>Prestige Rank: {miningPrestigeLevel} (boosts rare + crit rates)</p>
              </div>
            </div>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-2">
            <div className="court-card rounded-xl p-5">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Forge Tier</p>
              <p className="mt-2 text-lg font-semibold text-white">
                {currentForge?.name || 'Forge'}
              </p>
              {currentForge?.description && (
                <p className="mt-2 text-xs text-gray-400">{currentForge.description}</p>
              )}
              <p className="mt-3 text-xs text-gray-400">Level {miningForgeLevel}</p>
              <div className="mt-4 rounded-xl border border-yellow-700/30 bg-gray-950/70 p-4">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Forge Upgrade</p>
                {nextForge ? (
                  <>
                    <p className="mt-2 text-sm font-semibold text-white">{nextForge.name}</p>
                    <p className="mt-1 text-xs text-gray-400">
                      Requires mining level {nextForge.requiredMiningLevel} · {nextForge.price}g
                    </p>
                    {nextForge.description && (
                      <p className="mt-2 text-xs text-gray-400">{nextForge.description}</p>
                    )}
                    <button
                      type="button"
                      onClick={handleUpgradeForge}
                      className={`mt-3 w-full rounded-lg px-3 py-2 text-xs font-semibold ${
                        miningLevel >= nextForge.requiredMiningLevel && gold >= nextForge.price
                          ? 'action-primary text-white'
                          : 'bg-gray-700 text-gray-300'
                      }`}
                      disabled={miningLevel < nextForge.requiredMiningLevel || gold < nextForge.price}
                    >
                      Upgrade Forge
                    </button>
                  </>
                ) : (
                  <p className="mt-2 text-xs text-gray-400">Forge fully upgraded.</p>
                )}
              </div>
            </div>
          </div>

          <div className="mt-8 grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Ore Inventory</p>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                {miningOres.map((ore) => (
                  <div key={ore.id} className="rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                    <div className="flex items-center gap-3">
                      {ore.image && (
                        <img
                          src={ore.image}
                          alt={ore.name}
                          className="h-10 w-10 rounded-lg object-contain"
                        />
                      )}
                      <p className="text-sm font-semibold text-white">{ore.name}</p>
                    </div>
                    <p className="mt-2 text-xs text-gray-400">Stored</p>
                    <p className="mt-1 text-xl font-semibold text-yellow-300">
                      {getItemCount(inventory, ore.id)}
                    </p>
                  </div>
                ))}
              </div>
            </div>
            <div className="image-panel image-panel-inventory ornament-frame p-6">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Last Haul</p>
                {lastResultList.length === 0 ? (
                  <p className="mt-3 text-sm text-gray-300">No mining rewards yet.</p>
                ) : (
                  <>
                    <p className="mt-2 text-xs text-gray-400">Run tier: {lastResult?.tier || 1}</p>
                    <ul className="mt-3 space-y-2 text-sm text-gray-300">
                      {lastResultList.map((item) => (
                        <li key={item.id} className="flex items-center justify-between">
                          <span>{item.name}</span>
                          <span className="text-yellow-200">+{item.amount}</span>
                        </li>
                      ))}
                    </ul>
                  </>
                )}
              </div>
            </div>
          </div>

          <div className="mt-8">
            <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Mining Contracts</p>
              <span
                className={`${
                  miningContractTokens > 0 ? 'token-glow ' : ''
                }inline-flex items-center gap-2 rounded-full bg-yellow-500/10 px-3 py-1 text-[10px] font-semibold text-yellow-200`}
              >
                <span className="inline-flex h-4 w-4 items-center justify-center rounded-full bg-yellow-500/20 text-[10px] text-yellow-200">
                  <svg viewBox="0 0 24 24" className="h-3 w-3" fill="currentColor" aria-hidden="true">
                    <path d="M12 2l8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6l8-4zm0 4l-4 2v4c0 3.6 2.2 6.2 4 7 1.8-.8 4-3.4 4-7V8l-4-2z" />
                  </svg>
                </span>
                Tokens: {miningContractTokens}
              </span>
            </div>
            <div className="grid gap-6 lg:grid-cols-2">
            {['daily', 'weekly'].map((type) => {
              const contract = miningContracts?.[type];
              const ore = miningOres.find((item) => item.id === contract?.oreId);
              const owned = contract ? getItemCount(inventory, contract.oreId) : 0;
              const isClaimed = contract?.claimed;
              const canDeliver = contract && owned >= contract.amount && !isClaimed;
              const timeLeft = contract?.expiresAt ? Math.max(0, contract.expiresAt - now) : 0;
              return (
                <div key={type} className="court-card rounded-2xl p-6">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">
                    {type === 'weekly' ? 'Weekly Contract' : 'Daily Contract'}
                  </p>
                  {contract ? (
                    <div className="mt-3 space-y-2 text-sm text-gray-300">
                      <p className="text-white font-semibold">Deliver {contract.amount} {ore?.name || 'Ore'}</p>
                      <p>Reward: {contract.rewardGold} gold + {contract.rewardXp} XP</p>
                      <p>Progress: {owned}/{contract.amount}</p>
                      <p>Time left: {formatDuration(timeLeft)}</p>
                      {isClaimed ? (
                        <span className="inline-flex rounded-full bg-yellow-500/10 px-3 py-1 text-xs text-yellow-200">
                          Completed
                        </span>
                      ) : (
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            type="button"
                            onClick={() => handleDeliverContract(type)}
                            className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                              canDeliver ? 'action-primary text-white' : 'bg-gray-700 text-gray-300'
                            }`}
                            disabled={!canDeliver}
                          >
                            Deliver Ore
                          </button>
                          <div className="relative group">
                            <button
                              type="button"
                              onClick={() => handleRefreshContract(type)}
                              className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                                miningContractTokens > 0 ? 'action-ghost text-yellow-200' : 'bg-gray-700 text-gray-300'
                              }`}
                              disabled={miningContractTokens <= 0}
                            >
                              Refresh ({miningContractTokens})
                            </button>
                            <div className="pointer-events-none absolute left-1/2 top-full z-20 mt-2 w-44 -translate-x-1/2 rounded-lg border border-yellow-700/30 bg-gray-950/95 px-3 py-2 text-[10px] text-gray-200 opacity-0 transition duration-200 ease-out group-hover:opacity-100 group-hover:translate-y-0 translate-y-1 group-hover:shadow-[0_0_12px_rgba(250,204,21,0.35)]">
                              <div className="flex items-start gap-2">
                                <span className="mt-0.5 inline-flex h-4 w-4 items-center justify-center rounded-full bg-yellow-500/20 text-[10px] text-yellow-200">
                                  i
                                </span>
                                <span>Uses one token to reroll this contract.</span>
                              </div>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  ) : (
                    <p className="mt-3 text-sm text-gray-300">Contract parchment is being prepared.</p>
                  )}
                </div>
              );
            })}
            </div>
          </div>

          <div className="mt-8 grid gap-6 lg:grid-cols-[1.1fr_0.9fr]">
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Worker Hirelings</p>
              <p className="mt-2 text-sm text-gray-300">
                Passive miners add extra ticks while you are away.
              </p>
              <p className="mt-2 text-xs text-gray-400">Total bonus: +{hirelingTicksPerHour} ticks/hour</p>
              {hirelingBreakdown.length > 0 && (
                <details
                  className="mt-2 rounded-lg border border-yellow-700/20 bg-gray-950/70 px-3 py-2 text-xs text-gray-400"
                  open={miningHirelingsOwned.length > 0}
                >
                  <summary className="flex cursor-pointer items-center justify-between text-yellow-200">
                    <span>Hireling contributions</span>
                    <span className="text-[10px] text-yellow-200">▾</span>
                  </summary>
                  <div className="mt-2 space-y-1">
                    {hirelingBreakdown.map((entry) => (
                      <div key={entry.id} className="flex items-center justify-between">
                        <span>{entry.name}</span>
                        <span className="text-yellow-200">{entry.count} ticks</span>
                      </div>
                    ))}
                  </div>
                </details>
              )}
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                {miningHirelings.map((hireling) => {
                  const owned = miningHirelingsOwned.includes(hireling.id);
                  const meetsLevel = miningLevel >= hireling.requiredMiningLevel;
                  const canHire = !owned && meetsLevel && gold >= hireling.price;
                  const refundRate = hireling.refundRate ?? 0.4;
                  const refundAmount = Math.max(0, Math.round(hireling.price * refundRate));
                  return (
                    <div key={hireling.id} className="rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                      <p className="text-sm font-semibold text-white">{hireling.name}</p>
                      <p className="mt-1 text-xs text-gray-400">{hireling.description}</p>
                      <p className="mt-2 text-xs text-gray-500">+{hireling.ticksPerHour} ticks/hour</p>
                      <p className="mt-2 text-xs text-gray-500">
                        Requires L{hireling.requiredMiningLevel} · {hireling.price}g
                      </p>
                      {owned && (
                        <p className="mt-2 text-xs text-gray-500">Dismiss refund: {refundAmount}g</p>
                      )}
                      <span className={`mt-3 inline-flex rounded-full px-3 py-1 text-xs ${
                        owned ? 'bg-yellow-500/10 text-yellow-200' : 'bg-gray-800 text-gray-400'
                      }`}>
                        {owned ? 'Hired' : 'Not hired'}
                      </span>
                      <div className="mt-3 grid gap-2 sm:grid-cols-2">
                        <button
                          type="button"
                          onClick={() => handleHirelingPurchase(hireling.id)}
                          className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                            canHire ? 'action-primary text-white' : 'bg-gray-700 text-gray-300'
                          }`}
                          disabled={!canHire}
                        >
                          Hire
                        </button>
                        <button
                          type="button"
                          onClick={() => handleOpenDismiss(hireling.id)}
                          className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                            owned ? 'border border-yellow-700/40 text-yellow-200' : 'bg-gray-700 text-gray-300'
                          }`}
                          disabled={!owned}
                        >
                          Dismiss
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
            <div className="image-panel image-panel-market ornament-frame p-6">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Passive Summary</p>
                <p className="mt-3 text-sm text-gray-300">
                  Hirelings add {hirelingTicksPerHour} extra ticks per hour while mining.
                </p>
                <p className="mt-2 text-xs text-gray-400">
                  Bonuses stack with your pickaxe and boosters.
                </p>
              </div>
            </div>
          </div>

          <div className="mt-8 grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Mining Boosters</p>
              <p className="mt-2 text-sm text-gray-300">
                Arm a consumable to increase mining XP on your next claim.
              </p>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                {miningConsumables.map((booster) => {
                  const owned = getItemCount(inventory, booster.id);
                  const isArmed = activeBoostId === booster.id;
                  const cooldownUntil = boosterCooldowns[booster.id] || 0;
                  const isOnCooldown = cooldownUntil > Date.now();
                  const cooldownLabel = isOnCooldown ? formatDuration(cooldownUntil - Date.now()) : 'Ready';
                  const meetsLevel = miningLevel >= booster.requiredMiningLevel;
                  const canArm = owned > 0 && !isArmed && !isOnCooldown && meetsLevel;
                  return (
                    <div key={booster.id} className="rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                      <div className="flex items-center gap-2">
                        <span className="inline-flex h-7 w-7 items-center justify-center rounded-full bg-yellow-500/10">
                          {renderBoosterIcon(booster.id)}
                        </span>
                        <p className="text-sm font-semibold text-white">{booster.name}</p>
                      </div>
                      <p className="mt-1 text-xs text-gray-400">{booster.description}</p>
                      <div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-xs text-gray-300">
                        <span>Owned: {owned}</span>
                        <span>Req L{booster.requiredMiningLevel}</span>
                        <span>Cooldown: {cooldownLabel}</span>
                        {isArmed ? (
                          <span className="rounded-full bg-yellow-500/10 px-3 py-1 text-xs text-yellow-200">
                            Armed
                          </span>
                        ) : (
                          <button
                            type="button"
                            onClick={() => handleArmBooster(booster.id)}
                            className={`rounded-lg px-3 py-1 text-xs font-semibold ${
                              canArm ? 'action-primary text-white' : 'bg-gray-700 text-gray-300'
                            }`}
                            disabled={!canArm}
                          >
                            Arm
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
            <div className="image-panel image-panel-market ornament-frame p-6">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Active Booster</p>
                {activeBoost ? (
                  <div className="mt-3 text-sm text-gray-300">
                    <p className="font-semibold text-white">{activeBoost.name}</p>
                    <p className="mt-1 text-xs text-gray-400">{activeBoost.description}</p>
                    <p className="mt-1 text-xs text-gray-400">Req level {activeBoost.requiredMiningLevel}</p>
                  </div>
                ) : (
                  <p className="mt-3 text-sm text-gray-300">No booster armed.</p>
                )}
                {lastResult?.boosterId && (
                  <p className="mt-3 text-xs text-gray-400">
                    Last claim used: {getMiningConsumable(lastResult.boosterId)?.name || 'Booster'}
                  </p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {showStopModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4">
          <div className="w-full max-w-md rounded-2xl border border-yellow-700/30 bg-gray-950/95 p-6 shadow-xl">
            <p className="text-sm uppercase tracking-[0.3em] text-yellow-400">Stop Mining</p>
            <h2 className="mt-3 text-xl font-semibold text-white">End your mining run early?</h2>
            <p className="mt-2 text-sm text-gray-300">
              Stopping now will apply a 4-hour cooldown. Your current haul will be claimed.
            </p>
            <p className="mt-2 text-xs text-gray-400">
              Cooldown ends at {new Date(Date.now() + 4 * 60 * 60 * 1000).toLocaleString()}.
            </p>
            <div className="mt-6 flex items-center justify-end gap-3">
              <button
                type="button"
                onClick={handleCancelStopMining}
                className="rounded-lg border border-yellow-700/40 px-4 py-2 text-xs font-semibold text-yellow-200"
              >
                Keep Mining
              </button>
              <button
                type="button"
                onClick={handleConfirmStopMining}
                className="rounded-lg px-4 py-2 text-xs font-semibold action-primary text-white"
              >
                Stop & Claim
              </button>
            </div>
          </div>
        </div>
      )}
      {showDismissModal && dismissHireling && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4">
          <div className="w-full max-w-md rounded-2xl border border-yellow-700/30 bg-gray-950/95 p-6 shadow-xl">
            <p className="text-sm uppercase tracking-[0.3em] text-yellow-400">Dismiss Hireling</p>
            <h2 className="mt-3 text-xl font-semibold text-white">
              Dismiss {dismissHireling.name}?
            </h2>
            <p className="mt-2 text-sm text-gray-300">
              This hireling will stop providing ticks. You will receive a refund.
            </p>
            <p className="mt-2 text-xs text-gray-400">
              Refund: {Math.max(0, Math.round(dismissHireling.price * (dismissHireling.refundRate ?? 0.4)))}g
            </p>
            <div className="mt-6 flex items-center justify-end gap-3">
              <button
                type="button"
                onClick={handleCancelDismiss}
                className="rounded-lg border border-yellow-700/40 px-4 py-2 text-xs font-semibold text-yellow-200"
              >
                Keep Hireling
              </button>
              <button
                type="button"
                onClick={handleConfirmDismiss}
                className="rounded-lg px-4 py-2 text-xs font-semibold action-primary text-white"
              >
                Dismiss
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import Sidebar from '../components/Sidebar';
import XpBar from '../components/XpBar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import {
  formatDuration,
  getDailyVeinBonus,
  getWeeklySurgeBonus,
  getMiningConsumable,
  miningOres,
  getMiningXpForLevel,
  getTierByMiningLevel,
  getPickaxeUpgrade,
  getForgeUpgrade,
  getOresForTier,
  rollMiningTick,
} from '../data/miningData';
import { getZoneModifiers } from '../data/zonesData';
import { addItems } from '../services/inventoryService';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

export default function MiningClick() {
  const [profile, setProfile] = useState(null);
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    if (!MOCK_AUTH) {
      return undefined;
    }

    const username = authService.getCurrentUsername();
    const nextProfile = characterService.getMockProfile(username);
    setProfile(nextProfile);

    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const miningSession = profile?.miningSession || null;
  const endAt = miningSession?.endAt || 0;
  const remainingMs = endAt - now;
  const isMining = remainingMs > 0;

  const miningLevel = profile?.miningLevel ?? 1;
  const miningXp = profile?.miningXp ?? 0;
  const pickaxeLevel = profile?.pickaxeLevel ?? 1;
  const miningForgeLevel = profile?.miningForgeLevel ?? 1;
  const miningPrestigeLevel = profile?.miningPrestigeLevel ?? 0;
  const inventory = profile?.inventory || {};
  const miningHirelingsOwned = profile?.miningHirelings || [];
  const miningClickState = profile?.miningClickState || null;
  const activeBoostId = profile?.activeMiningBoost || null;
  const activeBoost = activeBoostId ? getMiningConsumable(activeBoostId) : null;
  const currentPickaxe = getPickaxeUpgrade(pickaxeLevel);
  const zoneModifiers = getZoneModifiers(profile);
  const zoneMiningYieldMultiplier = zoneModifiers.miningYieldMultiplier ?? 1;
  const zoneMiningXpMultiplier = zoneModifiers.miningXpMultiplier ?? 1;
  const dailyVeinBonus = useMemo(() => getDailyVeinBonus(now), [now]);
  const weeklySurgeBonus = useMemo(() => getWeeklySurgeBonus(now), [now]);

  const clickNode = miningClickState?.node || null;
  const clickPreview = miningClickState?.preview || null;
  const lastClickReward = miningClickState?.lastClickReward || null;
  const pendingYield = miningClickState?.pendingYield || {};
  const nodeTier = clickNode?.tier || getTierByMiningLevel(miningLevel);
  const nodeDurability = clickNode?.durability ?? 0;
  const nodeMaxDurability = clickNode?.maxDurability ?? 0;
  const nodeDurabilityPct = nodeMaxDurability > 0
    ? Math.max(0, Math.min(100, Math.round((nodeDurability / nodeMaxDurability) * 100)))
    : 0;
  const momentumValue = miningClickState?.momentum?.value || 0;
  const momentumMax = miningClickState?.momentum?.max || 100;
  const momentumPct = momentumMax > 0
    ? Math.max(0, Math.min(100, Math.round((momentumValue / momentumMax) * 100)))
    : 0;
  const momentumMultiplier = 1 + Math.min(0.1, momentumValue * 0.001);

  const titleBonus = profile?.title ? 1.03 : 1;
  const hirelingBonus = 1 + Math.min(0.12, miningHirelingsOwned.length * 0.01);
  const progressBonus = 1 + Math.min(0.6, miningLevel * 0.01 + pickaxeLevel * 0.02 + miningPrestigeLevel * 0.01);
  const clickEfficiency = Math.min(
    1.6,
    0.6 * progressBonus * titleBonus * hirelingBonus * momentumMultiplier * zoneMiningYieldMultiplier
  );
  const clickBaseXp = 1 + Math.floor(miningLevel / 3) + Math.floor(pickaxeLevel / 2);
  const clickDamage = Math.max(
    1,
    Math.round((1 + Math.floor(miningLevel / 5) + Math.floor(pickaxeLevel / 2)) * (1 + miningPrestigeLevel * 0.02))
  );
  const nodeBreakMultiplier = 1.4;
  const clickCooldownMs = 250;

  const diversityTier = Math.min(6, nodeTier + Math.floor(pickaxeLevel / 2));
  const basePool = getOresForTier(diversityTier);
  const rarePool = getOresForTier(Math.min(6, diversityTier + 1)).filter(
    (ore) => ore.tier > diversityTier
  );
  const breakPool = rarePool.length > 0 ? rarePool : basePool;

  const xpToNext = getMiningXpForLevel(miningLevel);

  const getClickPreview = (nodeTier) => {
    const tier = nodeTier || getTierByMiningLevel(miningLevel);
    const forge = getForgeUpgrade(miningForgeLevel) || { rareChanceBonus: 0, mishapReduction: 0 };
    const prestigeRareBonus = Math.min(0.06, miningPrestigeLevel * 0.01);
    const prestigeCritBonus = Math.min(0.04, miningPrestigeLevel * 0.005);
    const baseRareChance = 0.02 + pickaxeLevel * 0.003 + miningLevel * 0.0012 + (forge.rareChanceBonus || 0);
    const rareChance = Math.min(0.18, baseRareChance + prestigeRareBonus);
    const baseCritChance = 0.05 + pickaxeLevel * 0.007;
    const critChance = Math.min(0.18, baseCritChance + prestigeCritBonus);
    const bonusMultiplier = 1 + Math.min(0.2, pickaxeLevel * 0.015);
    const baseScale = 0.6;
    const minAmount = Math.max(1, Math.round(0.35 * bonusMultiplier * baseScale));
    const maxAmount = Math.max(1, Math.round(1.3 * bonusMultiplier * baseScale));
    return {
      tier,
      minAmount,
      maxAmount,
      critChance,
      rareChance,
    };
  };

  const buildClickNode = (tierOverride = null) => {
    const tier = tierOverride || getTierByMiningLevel(miningLevel);
    const baseDurability = 10 + tier * 6;
    const pickaxeBoost = Math.floor(pickaxeLevel * 1.5);
    const maxDurability = baseDurability + pickaxeBoost;
    return {
      id: `node-${Date.now()}`,
      tier,
      maxDurability,
      durability: maxDurability,
      createdAt: Date.now(),
    };
  };

  const ensureClickState = () => {
    const nextState = miningClickState ? { ...miningClickState } : {};
    const nodeTier = nextState.node?.tier || getTierByMiningLevel(miningLevel);
    let changed = false;

    if (!nextState.node || nextState.node.durability == null) {
      nextState.node = buildClickNode(nodeTier);
      changed = true;
    }

    if (!nextState.momentum) {
      nextState.momentum = { value: 0, max: 100, updatedAt: Date.now() };
      changed = true;
    }

    if (!nextState.pendingYield) {
      nextState.pendingYield = {};
      changed = true;
    }

    if (!nextState.preview) {
      nextState.preview = getClickPreview(nextState.node.tier);
      changed = true;
    }

    if (nextState.preview && nextState.preview.tier !== nextState.node.tier) {
      nextState.preview = getClickPreview(nextState.node.tier);
      changed = true;
    }

    return { nextState, changed };
  };

  useEffect(() => {
    if (!MOCK_AUTH || !profile) {
      return;
    }

    const { nextState, changed } = ensureClickState();
    if (!changed) {
      return;
    }

    const updated = characterService.updateMockProfile({
      miningClickState: nextState,
    });
    setProfile(updated);
  }, [profile, miningLevel, pickaxeLevel]);

  const applyMiningXp = (xpGain) => {
    let nextLevel = miningLevel;
    let nextXp = miningXp + xpGain;
    let xpNeeded = getMiningXpForLevel(nextLevel);

    while (nextXp >= xpNeeded) {
      nextXp -= xpNeeded;
      nextLevel += 1;
      xpNeeded = getMiningXpForLevel(nextLevel);
    }

    return { nextLevel, nextXp };
  };

  const handleClickMine = () => {
    if (!MOCK_AUTH || !profile || !miningSession || !isMining) {
      return;
    }

    const { nextState } = ensureClickState();
    const lastClickAt = nextState.lastClickAt || 0;
    const clickCooldownMs = 250;
    if (now - lastClickAt < clickCooldownMs) {
      return;
    }

    const tier = nextState.node?.tier || getTierByMiningLevel(miningLevel);
    const available = getOresForTier(Math.min(6, tier + Math.floor(pickaxeLevel / 2)));
    if (available.length === 0) {
      return;
    }

    const titleBonus = profile.title ? 1.03 : 1;
    const hirelingBonus = 1 + Math.min(0.12, miningHirelingsOwned.length * 0.01);
    const progressBonus = 1 + Math.min(0.6, miningLevel * 0.01 + pickaxeLevel * 0.02 + miningPrestigeLevel * 0.01);
    const clickEfficiency = Math.min(
      1.6,
      0.6 * progressBonus * titleBonus * hirelingBonus * momentumMultiplier * zoneMiningYieldMultiplier
    );

    const { yieldMap, xpMultiplier, event } = rollMiningTick({
      miningLevel,
      pickaxeLevel,
      forgeLevel: miningForgeLevel,
      dailyVein: dailyVeinBonus,
      weeklySurge: weeklySurgeBonus,
      prestigeLevel: miningPrestigeLevel,
    });

    const claimedYield = {};
    Object.entries(yieldMap).forEach(([oreId, amount]) => {
      const adjustedAmount = Math.max(1, Math.round(amount * clickEfficiency));
      claimedYield[oreId] = (claimedYield[oreId] || 0) + adjustedAmount;
    });

    const clickBaseXp = 1 + Math.floor(miningLevel / 3) + Math.floor(pickaxeLevel / 2);
    const clickXp = Math.max(1, Math.round(clickBaseXp * (xpMultiplier || 1) * zoneMiningXpMultiplier));

    let nextInventory = { ...inventory };
    const nextPendingYield = { ...(nextState.pendingYield || {}) };
    Object.entries(claimedYield).forEach(([oreId, amount]) => {
      nextPendingYield[oreId] = (nextPendingYield[oreId] || 0) + amount;
    });

    const baseDamage = 1 + Math.floor(miningLevel / 5) + Math.floor(pickaxeLevel / 2);
    const damage = Math.max(1, Math.round(baseDamage * (1 + miningPrestigeLevel * 0.02)));
    const remainingDurability = Math.max(0, (nextState.node?.durability || 0) - damage);
    let nextNode = { ...nextState.node, durability: remainingDurability };
    const burstReward = {};
    let burstXp = 0;

    if (remainingDurability <= 0) {
      const burst = rollMiningTick({
        miningLevel,
        pickaxeLevel,
        forgeLevel: miningForgeLevel,
        dailyVein: dailyVeinBonus,
        weeklySurge: weeklySurgeBonus,
        prestigeLevel: miningPrestigeLevel,
      });
      Object.entries(burst.yieldMap).forEach(([oreId, amount]) => {
        const adjustedAmount = Math.max(1, Math.round(amount * clickEfficiency * 1.4));
        burstReward[oreId] = (burstReward[oreId] || 0) + adjustedAmount;
      });
      burstXp = Math.max(1, Math.round(clickBaseXp * 1.4 * (burst.xpMultiplier || 1)));
      nextNode = buildClickNode(tier);
    }

    const totalXp = clickXp + burstXp;
    const { nextLevel: finalLevel, nextXp: finalXp } = applyMiningXp(totalXp);

    const totalYieldOnBreak = remainingDurability <= 0
      ? Object.entries({ ...nextPendingYield, ...burstReward }).reduce((acc, [oreId, amount]) => {
          acc[oreId] = (acc[oreId] || 0) + amount;
          return acc;
        }, {})
      : {};

    if (remainingDurability <= 0) {
      nextInventory = addItems(nextInventory, totalYieldOnBreak);
    }

    const nextMomentumValue = Math.min(
      nextState.momentum?.max || 100,
      (nextState.momentum?.value || 0) + 6
    );

    const nextClickState = {
      ...nextState,
      node: nextNode,
      lastClickAt: now,
      pendingYield: remainingDurability <= 0 ? {} : nextPendingYield,
      momentum: {
        value: nextMomentumValue,
        max: nextState.momentum?.max || 100,
        updatedAt: now,
      },
      lastClickReward: {
        yieldMap: totalYieldOnBreak,
        burstYield: burstReward,
        xpGained: totalXp,
        event,
        brokeNode: remainingDurability <= 0,
        timestamp: now,
      },
      preview: getClickPreview(nextNode.tier),
    };

    const updated = characterService.updateMockProfile({
      inventory: nextInventory,
      miningLevel: finalLevel,
      miningXp: finalXp,
      miningClickState: nextClickState,
    });

    setProfile(updated);
  };

  useEffect(() => {
    if (!MOCK_AUTH || !profile || !miningClickState?.momentum) {
      return;
    }

    const { value, updatedAt, max } = miningClickState.momentum;
    if (!value || !updatedAt) {
      return;
    }

    const elapsedSeconds = Math.floor((now - updatedAt) / 1000);
    if (elapsedSeconds <= 0) {
      return;
    }

    const decayRate = 3;
    const nextValue = Math.max(0, value - elapsedSeconds * decayRate);
    if (nextValue === value) {
      return;
    }

    const nextClickState = {
      ...miningClickState,
      momentum: {
        value: nextValue,
        max: max || 100,
        updatedAt: now,
      },
    };

    const updated = characterService.updateMockProfile({
      miningClickState: nextClickState,
    });

    setProfile(updated);
  }, [now, profile, miningClickState]);

  const canClick = isMining;
  const lastRewardItems = lastClickReward
    ? Object.entries(lastClickReward.yieldMap || {}).map(([oreId, amount]) => ({
        id: oreId,
        amount,
        name: (miningOres.find((ore) => ore.id === oreId) || {}).name || oreId,
      }))
    : [];
  const lastBurstItems = lastClickReward
    ? Object.entries(lastClickReward.burstYield || {}).map(([oreId, amount]) => ({
        id: oreId,
        amount,
        name: (miningOres.find((ore) => ore.id === oreId) || {}).name || oreId,
      }))
    : [];
  const pendingItems = Object.entries(pendingYield).map(([oreId, amount]) => ({
    id: oreId,
    amount,
    name: (miningOres.find((ore) => ore.id === oreId) || {}).name || oreId,
  }));

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Deepforge</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Click Mining</h1>
              <p className="mt-3 text-base text-gray-300">
                Strike active nodes to build up a stash that drops when the node breaks.
              </p>
            </div>
            <Link
              to="/mining"
              className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
            >
              Back to Mining
            </Link>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Mining Level</p>
              <p className="mt-2 text-2xl font-semibold text-white">{miningLevel}</p>
              <div className="mt-3">
                <XpBar current={miningXp} target={xpToNext} label="Mining XP" tone="cyan" />
              </div>
            </div>
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Session</p>
              <p className="mt-2 text-2xl font-semibold text-white">{isMining ? 'In Progress' : 'Idle'}</p>
              <p className="mt-2 text-sm text-gray-300">
                {isMining
                  ? `Time left: ${formatDuration(remainingMs)}`
                  : 'Start a run on the main mining page.'}
              </p>
            </div>
            <div className="image-panel image-panel-housing ornament-frame p-4">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Pickaxe</p>
                <p className="mt-2 text-2xl font-semibold text-white">{currentPickaxe?.name || 'Pickaxe'}</p>
                <p className="mt-2 text-xs text-gray-400">{currentPickaxe?.rarity || 'Common'}</p>
              </div>
            </div>
          </div>

          <div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_0.9fr]">
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Node</p>
              <div className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                <div className="flex items-center justify-between text-xs text-gray-300">
                  <span>Durability</span>
                  <span className="text-yellow-200">{nodeDurability}/{nodeMaxDurability}</span>
                </div>
                <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-black/50">
                  <div
                    className="h-full rounded-full bg-emerald-400/70 transition-all"
                    style={{ width: `${nodeDurabilityPct}%` }}
                  />
                </div>
                <div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-gray-400">
                  <span>Node tier: {nodeTier}</span>
                  <span>Momentum: {momentumValue}/{momentumMax}</span>
                </div>
              </div>
              <div className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Node Stash</p>
                {pendingItems.length === 0 ? (
                  <p className="mt-2 text-xs text-gray-400">No ores stored yet.</p>
                ) : (
                  <div className="mt-3 space-y-1 text-xs text-gray-400">
                    {pendingItems.map((item) => (
                      <div key={item.id} className="flex items-center justify-between">
                        <span>{item.name}</span>
                        <span className="text-yellow-200">{item.amount}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              <div className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Node Break Loot</p>
                <p className="mt-2 text-xs text-gray-400">
                  Breaks grant one bonus roll at +{Math.round((nodeBreakMultiplier - 1) * 100)}% yield.
                </p>
                <div className="mt-3 flex flex-wrap gap-2">
                  {breakPool.map((ore) => (
                    <span
                      key={ore.id}
                      className="rounded-full border border-yellow-700/30 bg-yellow-500/10 px-3 py-1 text-[10px] uppercase tracking-[0.2em] text-yellow-200"
                    >
                      {ore.name}
                    </span>
                  ))}
                </div>
              </div>
              <div className="mt-4 flex flex-wrap items-center gap-4">
                <button
                  type="button"
                  onClick={handleClickMine}
                  disabled={!canClick}
                  className={`inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold ${
                    canClick ? 'action-primary text-white' : 'bg-gray-700 text-gray-300'
                  }`}
                >
                  Mine Node
                </button>
                <span className="text-xs text-gray-400">
                  {canClick ? 'Keep clicking to build momentum.' : 'Start a run to enable clicks.'}
                </span>
              </div>
              {lastClickReward && (
                <div className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Last Click</p>
                  <div className="mt-2 flex flex-wrap items-center gap-3 text-xs text-gray-300">
                    <span className="rounded-full bg-yellow-500/10 px-3 py-1 text-yellow-200">
                      {lastClickReward.event || 'normal'}
                    </span>
                    <span className="text-gray-400">+{lastClickReward.xpGained} XP</span>
                    {lastClickReward.brokeNode && (
                      <span className="rounded-full bg-emerald-500/10 px-3 py-1 text-emerald-200">
                        Node broke!
                      </span>
                    )}
                  </div>
                  {lastRewardItems.length > 0 && (
                    <div className="mt-3 space-y-1 text-xs text-gray-400">
                      {lastRewardItems.map((item) => (
                        <div key={item.id} className="flex items-center justify-between">
                          <span>{item.name}</span>
                          <span className="text-yellow-200">+{item.amount}</span>
                        </div>
                      ))}
                    </div>
                  )}
                  {lastBurstItems.length > 0 && (
                    <div className="mt-3 space-y-1 text-xs text-gray-400">
                      <p className="text-xs uppercase tracking-[0.3em] text-gray-500">Break bonus</p>
                      {lastBurstItems.map((item) => (
                        <div key={item.id} className="flex items-center justify-between">
                          <span>{item.name}</span>
                          <span className="text-yellow-200">+{item.amount}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="image-panel image-panel-market ornament-frame p-6">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Click Preview</p>
                <p className="mt-3 text-sm text-gray-300">
                  {clickPreview
                    ? `Ore range: ${clickPreview.minAmount}-${clickPreview.maxAmount}`
                    : 'Click data loading...'}
                </p>
                {clickPreview && (
                  <div className="mt-3 space-y-1 text-xs text-gray-400">
                    <p>Crit chance: {Math.round(clickPreview.critChance * 100)}%</p>
                    <p>Rare chance: {Math.round(clickPreview.rareChance * 100)}%</p>
                  </div>
                )}
                <div className="mt-4">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Momentum</p>
                  <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-black/50">
                    <div
                      className="h-full rounded-full bg-cyan-400/70 transition-all"
                      style={{ width: `${momentumPct}%` }}
                    />
                  </div>
                  <p className="mt-2 text-xs text-gray-400">
                    Passive bonus: +{Math.round((momentumMultiplier - 1) * 100)}%
                  </p>
                </div>
                <div className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                  <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Economy Math</p>
                  <div className="mt-3 space-y-1 text-xs text-gray-400">
                    <p>Click efficiency: x{clickEfficiency.toFixed(2)} (cap 1.60)</p>
                    <p>Base click XP: {clickBaseXp} · Zone XP x{zoneMiningXpMultiplier.toFixed(2)}</p>
                    <p>Node damage per click: {clickDamage}</p>
                    <p>Click cooldown: {clickCooldownMs}ms</p>
                    <p>Break bonus: +{Math.round((nodeBreakMultiplier - 1) * 100)}% yield</p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="mt-8 grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
            <div className="court-card rounded-2xl p-6">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Ore Inventory</p>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                {miningOres.map((ore) => (
                  <div key={ore.id} className="rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                    <div className="flex items-center gap-3">
                      {ore.image && (
                        <img
                          src={ore.image}
                          alt={ore.name}
                          className="h-10 w-10 rounded-lg object-contain"
                        />
                      )}
                      <p className="text-sm font-semibold text-white">{ore.name}</p>
                    </div>
                    <p className="mt-2 text-xs text-gray-400">Stored</p>
                    <p className="mt-1 text-xl font-semibold text-yellow-300">
                      {inventory[ore.id] || 0}
                    </p>
                  </div>
                ))}
              </div>
            </div>
            <div className="image-panel image-panel-inventory ornament-frame p-6">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Mining Momentum</p>
                <p className="mt-3 text-sm text-gray-300">
                  Momentum boosts passive mining while you actively click.
                </p>
                <div className="mt-4 rounded-xl border border-yellow-700/20 bg-gray-950/70 p-4">
                  <div className="flex items-center justify-between text-xs text-gray-300">
                    <span>Momentum</span>
                    <span className="text-yellow-200">{momentumValue}/{momentumMax}</span>
                  </div>
                  <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-black/50">
                    <div
                      className="h-full rounded-full bg-cyan-400/70 transition-all"
                      style={{ width: `${momentumPct}%` }}
                    />
                  </div>
                  <p className="mt-3 text-xs text-gray-400">
                    Passive bonus: +{Math.round((momentumMultiplier - 1) * 100)}%
                  </p>
                </div>
                <div className="mt-4 text-xs text-gray-400">
                  <p>Daily Vein: +25% {miningOres.find((ore) => ore.id === dailyVeinBonus.oreId)?.name || 'ore'} yield</p>
                  <p>Weekly Surge: +{Math.round((weeklySurgeBonus.xpMultiplier - 1) * 100)}% XP</p>
                  <p>Active boost: {activeBoost?.name || 'None'}</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import Sidebar from '../components/Sidebar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import { ensureGeneralMissions, getMissionProgress, isMissionComplete } from '../data/missionData';
import { getPlayerXpForLevel } from '../data/playerData';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';

export default function Missions() {
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    if (!MOCK_AUTH) {
      return;
    }

    const username = authService.getCurrentUsername();
    const nextProfile = characterService.getMockProfile(username);
    const { nextMissions, nextMeta, changed } = ensureGeneralMissions(
      nextProfile?.generalMissions,
      nextProfile,
      nextProfile?.generalMissionsMeta
    );

    if (changed) {
      const updated = characterService.updateMockProfile({
        generalMissions: nextMissions,
        generalMissionsMeta: nextMeta,
      });
      setProfile(updated);
    } else {
      setProfile(nextProfile);
    }
  }, []);

  const missions = profile?.generalMissions || [];
  const playerLevel = profile?.stats?.level ?? 1;
  const playerXp = profile?.stats?.xp ?? 0;
  const gold = profile?.stats?.gold ?? 0;

  const completedCount = useMemo(
    () => missions.filter((mission) => isMissionComplete(mission, profile)).length,
    [missions, profile]
  );

  const applyPlayerXp = (startLevel, startXp, gain) => {
    let nextLevel = startLevel;
    let nextXp = startXp + gain;
    let target = getPlayerXpForLevel(nextLevel);

    while (nextXp >= target) {
      nextXp -= target;
      nextLevel += 1;
      target = getPlayerXpForLevel(nextLevel);
    }

    return { nextLevel, nextXp };
  };

  const handleClaim = (missionId) => {
    if (!MOCK_AUTH || !profile) {
      return;
    }

    const missionIndex = missions.findIndex((mission) => mission.id === missionId);
    if (missionIndex === -1) {
      return;
    }

    const mission = missions[missionIndex];
    if (mission.claimed) {
      toast('Mission already claimed.', { icon: '✅' });
      return;
    }

    if (!isMissionComplete(mission, profile)) {
      toast.error('Mission not complete yet.');
      return;
    }

    const nextMissions = [...missions];
    nextMissions[missionIndex] = { ...mission, claimed: true };

    const xpGain = mission.rewardXp || 0;
    const { nextLevel, nextXp } = applyPlayerXp(playerLevel, playerXp, xpGain);
    const bonusLevels = mission.rewardLevels || 0;
    const finalLevel = nextLevel + bonusLevels;
    const levelGain = finalLevel - playerLevel;

    const updated = characterService.updateMockProfile({
      generalMissions: nextMissions,
      stats: {
        ...profile.stats,
        level: finalLevel,
        xp: nextXp,
        gold: gold + (mission.rewardGold || 0),
      },
    });

    setProfile(updated);
    toast.success(`Mission claimed +${mission.rewardGold}g +${levelGain} level +${xpGain} XP.`);
  };

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm2.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-8 shadow-xl backdrop-blur court-reveal glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Progression</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">General Missions</h1>
              <p className="mt-3 text-base text-gray-300">
                Complete long-term goals to boost your character level and gold.
              </p>
            </div>
            <Link
              to="/housing"
              className="inline-flex items-center rounded-full px-4 py-2 text-xs font-semibold text-yellow-200 action-ghost"
            >
              Back to Housing
            </Link>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Player Level</p>
              <p className="mt-2 text-2xl font-semibold text-white">{playerLevel}</p>
            </div>
            <div className="court-card rounded-xl p-4">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Gold</p>
              <p className="mt-2 text-2xl font-semibold text-yellow-300">{gold}</p>
            </div>
            <div className="image-panel image-panel-housing ornament-frame p-4">
              <div className="image-panel-content">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-300">Completed</p>
                <p className="mt-2 text-2xl font-semibold text-white">{completedCount}/{missions.length}</p>
              </div>
            </div>
          </div>

          <div className="mt-8 space-y-4">
            {missions.map((mission) => {
              const progress = getMissionProgress(mission, profile);
              const isComplete = isMissionComplete(mission, profile);
              return (
                <div
                  key={mission.id}
                  className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-yellow-700/20 bg-gray-950/70 p-4"
                >
                  <div>
                    <p className="text-sm font-semibold text-white">{mission.label}</p>
                    <p className="mt-1 text-xs text-gray-400">
                      Progress: {mission.type === 'house' ? (isComplete ? 'Owned' : 'Not owned') : `${progress}/${mission.target}`}
                    </p>
                    <p className="mt-1 text-xs text-gray-400">
                      Rewards: +{mission.rewardLevels || 0} level · +{mission.rewardGold || 0}g · +{mission.rewardXp || 0} XP
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={() => handleClaim(mission.id)}
                    className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                      mission.claimed
                        ? 'bg-gray-700 text-gray-300'
                        : isComplete
                        ? 'action-primary text-white'
                        : 'bg-gray-700 text-gray-300'
                    }`}
                    disabled={!isComplete || mission.claimed}
                  >
                    {mission.claimed ? 'Claimed' : isComplete ? 'Claim Reward' : 'In Progress'}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import Sidebar from '../components/Sidebar';
import XpBar from '../components/XpBar';
import authService from '../services/AuthService';
import characterService from '../services/CharacterService';
import WorkshopService from '../services/WorkshopService';
import {
  getWorkshopItem,
  getWorkshopRecipe,
  getWorkshopXpForLevel,
  getWorkshopUpgrade,
  getNextWorkshopUpgrade,
  workshopStations,
  workshopItems,
} from '../data/workshopData';
import { miningOres, formatDuration } from '../data/miningData';
import { farmGoods } from '../data/farmData';
import { getItemCount, removeItems } from '../services/inventoryService';

const MOCK_AUTH = import.meta.env.VITE_MOCK_AUTH === 'true';
const FILTER_STORAGE_KEY = 'workshopFilters';

const buildNameMap = (items) =>
  items.reduce((acc, item) => {
    acc[item.id] = item.name;
    return acc;
  }, {});

const clampQuantity = (value, fallback = 1) => {
  const next = Number(value);
  if (!Number.isFinite(next)) {
    return fallback;
  }
  return Math.max(1, Math.floor(next));
};

export default function Workshop() {
  const [profile, setProfile] = useState(null);
  const [now, setNow] = useState(Date.now());
  const [quantities, setQuantities] = useState({});
  const [stationFilter, setStationFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [tagFilter, setTagFilter] = useState('all');
  const [showCraftableOnly, setShowCraftableOnly] = useState(false);
  const hasMountedRef = useRef(false);

  useEffect(() => {
    if (!MOCK_AUTH) {
      return;
    }

    const stored = localStorage.getItem(FILTER_STORAGE_KEY);
    if (stored) {
      try {
        const parsed = JSON.parse(stored);
        if (parsed?.stationFilter) {
          setStationFilter(parsed.stationFilter);
        }
        if (parsed?.tagFilter) {
          setTagFilter(parsed.tagFilter);
        }
        if (typeof parsed?.searchTerm === 'string') {
          setSearchTerm(parsed.searchTerm);
        }
        if (typeof parsed?.showCraftableOnly === 'boolean') {
          setShowCraftableOnly(parsed.showCraftableOnly);
        }
      } catch {
        localStorage.removeItem(FILTER_STORAGE_KEY);
      }
    }

    const username = authService.getCurrentUsername();
    if (!username) {
      return;
    }

    const nextProfile = characterService.getMockProfile(username);
    setProfile(nextProfile);

    const processed = WorkshopService.processWorkshopQueue({ now: Date.now() });
    if (processed.profile) {
      setProfile(processed.profile);
    }

    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!hasMountedRef.current) {
      return;
    }
    const payload = {
      stationFilter,
      tagFilter,
      searchTerm,
      showCraftableOnly,
    };
    localStorage.setItem(FILTER_STORAGE_KEY, JSON.stringify(payload));
  }, [stationFilter, tagFilter, searchTerm, showCraftableOnly]);

  useEffect(() => {
    if (!profile?.workshopQueue?.length) {
      return;
    }

    const nextFinish = Math.min(...profile.workshopQueue.map((job) => job.finishAt));
    if (nextFinish <= now) {
      const processed = WorkshopService.processWorkshopQueue({ now });
      if (processed.profile) {
        setProfile(processed.profile);
      }
      if (hasMountedRef.current && processed.completedJobs?.length) {
        toast.success(`Workshop complete: ${processed.completedJobs.length} craft(s) ready.`);
      }
    }
  }, [now, profile]);

  useEffect(() => {
    hasMountedRef.current = true;
  }, []);

  const miningNames = useMemo(() => buildNameMap(miningOres), []);
  const farmNames = useMemo(() => buildNameMap(farmGoods), []);

  const uiState = useMemo(() => WorkshopService.getWorkshopUiState({ profile, now }), [profile, now]);
  const workshopLevel = uiState?.workshopLevel ?? 1;
  const workshopXp = uiState?.workshopXp ?? 0;
  const workshopXpTarget = getWorkshopXpForLevel(workshopLevel);

  const upgrade = useMemo(() => getWorkshopUpgrade(uiState?.workshopUpgradeLevel ?? 1), [uiState]);
  const nextUpgrade = useMemo(() => getNextWorkshopUpgrade(uiState?.workshopUpgradeLevel ?? 1), [uiState]);

  const inventory = profile?.inventory || {};
  const workshopInventory = useMemo(() => {
    const craftedIds = new Set(workshopItems.map((item) => item.id));
    return Object.entries(inventory).reduce((acc, [itemId, amount]) => {
      if (craftedIds.has(itemId)) {
        acc[itemId] = amount;
      }
      return acc;
    }, {});
  }, [inventory]);
  const gold = profile?.stats?.gold ?? 0;
  const workshopInventoryTotal = useMemo(
    () => Object.values(workshopInventory).reduce((sum, amount) => sum + (amount || 0), 0),
    [workshopInventory]
  );

  const unlockedStations = useMemo(() => {
    if (!uiState) {
      return [];
    }
    const unlockedIds = new Set(uiState.stations.map((station) => station.id));
    return workshopStations.map((station) => ({
      ...station,
      unlocked: unlockedIds.has(station.id),
    }));
  }, [uiState]);

  const getInputName = (input) => {
    if (input.source === 'mining') {
      return miningNames[input.id] || input.id;
    }
    if (input.source === 'farm') {
      return farmNames[input.id] || input.id;
    }
    return input.id;
  };

  const getOwnedForInput = (input) => {
    return getItemCount(inventory, input.id);
  };

  const canCraft = (recipe, quantity) => {
    if (!profile) {
      return false;
    }
    const scaled = clampQuantity(quantity, 1);
    return recipe.inputs.every((input) => getOwnedForInput(input) >= input.amount * scaled);
  };

  const normalizedSearch = searchTerm.trim().toLowerCase();
  const matchesSearch = (recipe) => {
    if (!normalizedSearch) {
      return true;
    }
    const outputName = getOutputName(recipe).toLowerCase();
    const recipeId = recipe.id.toLowerCase();
    return outputName.includes(normalizedSearch) || recipeId.includes(normalizedSearch);
  };

  const getOutputName = (recipe) => {
    const output = recipe.outputs?.[0];
    if (!output) {
      return recipe.id;
    }
    return getWorkshopItem(output.id)?.name || output.id;
  };

  const getRecipeOutputName = (recipeId) => {
    const recipe = getWorkshopRecipe(recipeId);
    return recipe ? getOutputName(recipe) : recipeId;
  };

  const getRecipeTags = (recipe) => {
    const tags = new Set();
    recipe.inputs.forEach((input) => {
      if (input.source === 'mining') {
        tags.add('ore');
      }
      if (input.source === 'farm') {
        tags.add('crop');
      }
    });
    return Array.from(tags);
  };

  const filteredRecipePool = useMemo(() => {
    if (!uiState) {
      return [];
    }
    const stationIds = stationFilter === 'all' ? uiState.stations.map((station) => station.id) : [stationFilter];
    return stationIds.flatMap((stationId) => uiState.recipes[stationId] || []);
  }, [uiState, stationFilter]);

  const tagCounts = useMemo(() => {
    const counts = { ore: 0, crop: 0 };
    filteredRecipePool.forEach((recipe) => {
      const tags = getRecipeTags(recipe);
      if (tags.includes('ore')) {
        counts.ore += 1;
      }
      if (tags.includes('crop')) {
        counts.crop += 1;
      }
    });
    return counts;
  }, [filteredRecipePool]);

  const matchesTag = (recipe) => {
    if (tagFilter === 'all') {
      return true;
    }
    return getRecipeTags(recipe).includes(tagFilter);
  };

  const shouldShowRecipe = (recipe, quantity) => {
    if (!matchesSearch(recipe) || !matchesTag(recipe)) {
      return false;
    }
    if (showCraftableOnly && !canCraft(recipe, quantity)) {
      return false;
    }
    return true;
  };

  const filteredRecipeCount = useMemo(() => {
    return filteredRecipePool.filter((recipe) => shouldShowRecipe(recipe, quantities[recipe.id] || 1)).length;
  }, [filteredRecipePool, quantities, stationFilter, tagFilter, searchTerm, showCraftableOnly]);

  const handleQueue = (recipeId, quantity) => {
    if (!MOCK_AUTH || !profile) {
      return;
    }

    const scaled = clampQuantity(quantity, 1);
    const result = WorkshopService.queueWorkshopJob({ recipeId, quantity: scaled, now: Date.now() });
    if (!result.ok) {
      toast.error(result.reason || 'Unable to queue crafting job.');
      return;
    }

    setProfile(result.profile);
    toast.success('Crafting started.');
  };

  const handleUpgrade = () => {
    if (!MOCK_AUTH || !profile) {
      return;
    }
    const result = WorkshopService.upgradeWorkshop();
    if (!result.ok) {
      toast.error(result.reason || 'Upgrade unavailable.');
      return;
    }
    setProfile(result.profile);
    toast.success('Workshop upgraded.');
  };

  const handleSell = (itemId, quantity) => {
    if (!MOCK_AUTH || !profile) {
      return;
    }

    const item = getWorkshopItem(itemId);
    if (!item) {
      toast.error('Unknown crafted item.');
      return;
    }

    const owned = workshopInventory[itemId] || 0;
    const scaled = Math.min(owned, clampQuantity(quantity, 1));
    if (scaled <= 0) {
      toast.error('Not enough items to sell.');
      return;
    }

    const nextInventory = removeItems(inventory, { [itemId]: scaled });

    const updated = characterService.updateMockProfile({
      inventory: nextInventory,
      stats: {
        ...profile.stats,
        gold: gold + item.sellValue * scaled,
      },
    });

    setProfile(updated);
    toast.success(`Sold ${scaled} ${item.name}.`);
  };

  const handleSellAllCrafted = () => {
    if (!MOCK_AUTH || !profile) {
      return;
    }

    if (workshopInventoryTotal <= 0) {
      toast.error('No crafted items to sell.');
      return;
    }

    const totalValue = Object.entries(workshopInventory).reduce((sum, [itemId, amount]) => {
      const item = getWorkshopItem(itemId);
      if (!item) {
        return sum;
      }
      return sum + item.sellValue * amount;
    }, 0);

    const confirmed = window.confirm(
      `Sell all crafted items for ${totalValue} gold? This cannot be undone.`
    );
    if (!confirmed) {
      return;
    }

    const removalMap = Object.entries(workshopInventory).reduce((acc, [itemId, amount]) => {
      acc[itemId] = amount;
      return acc;
    }, {});

    const updated = characterService.updateMockProfile({
      inventory: removeItems(inventory, removalMap),
      stats: {
        ...profile.stats,
        gold: gold + totalValue,
      },
    });

    setProfile(updated);
    toast.success('All crafted items sold.');
  };

  const handleClearFilters = () => {
    setStationFilter('all');
    setTagFilter('all');
    setSearchTerm('');
    setShowCraftableOnly(false);
  };

  if (!uiState) {
    return (
      <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
        <Sidebar />
        <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 pt-24 text-gray-200">Loading Workshop...</div>
      </section>
    );
  }

  return (
    <section className="min-h-screen bg-center bg-cover bg-no-repeat bg-[url('./jbm.jpg')] bg-gray-900 bg-blend-multiply dashboard-shell lg:pl-64">
      <Sidebar />
      <div className="dashboard-orb orb-1" />
      <div className="dashboard-orb orb-2" />
      <div className="dashboard-orb orb-3" />
      <div className="relative z-10 mx-auto max-w-6xl px-6 py-16 pt-24">
        <div className="rounded-2xl p-6 shadow-xl backdrop-blur glass-panel">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="section-kicker text-xs uppercase tracking-[0.4em] text-yellow-500">Crafting Hub</p>
              <h1 className="mt-3 text-4xl font-extrabold text-white hero-title">Workshop</h1>
              <p className="mt-3 text-base text-gray-300">
                Convert mined ore and farm goods into crafted wares over time.
              </p>
            </div>
            <div className="rounded-xl border border-yellow-700/30 bg-gray-950/70 px-4 py-3 text-center">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Level</p>
              <p className="mt-1 text-3xl font-semibold text-yellow-300">{workshopLevel}</p>
            </div>
          </div>

          <div className="mt-6 grid gap-4 lg:grid-cols-[1.1fr_0.9fr]">
            <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-5">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Workshop XP</p>
              <div className="mt-3">
                <XpBar current={workshopXp} target={workshopXpTarget || 1} label="Workshop XP" tone="emerald" />
              </div>
              <div className="mt-3 flex flex-wrap items-center gap-2 text-xs text-gray-400">
                <span>Upgrade: {upgrade?.name || 'Basic Tools'}</span>
                <span>·</span>
                <span>Queue: {uiState.jobs.length} jobs</span>
              </div>
            </div>

            <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-5">
              <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Upgrade Tools</p>
              <p className="mt-2 text-xl font-semibold text-white">
                {nextUpgrade ? nextUpgrade.name : 'Maxed Workshop'}
              </p>
              <p className="mt-1 text-sm text-gray-300">
                {nextUpgrade
                  ? `Reduce crafting time to ${(nextUpgrade.durationMultiplier * 100).toFixed(0)}%.`
                  : 'All upgrades unlocked.'}
              </p>
              <div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-gray-400">
                <span>Gold: {gold}</span>
                {nextUpgrade ? <span>Cost: {nextUpgrade.cost}</span> : null}
              </div>
              <button
                type="button"
                onClick={handleUpgrade}
                disabled={!nextUpgrade || gold < nextUpgrade.cost}
                className={`mt-4 inline-flex items-center rounded-lg px-4 py-2 text-xs font-semibold ${
                  nextUpgrade && gold >= nextUpgrade.cost
                    ? 'action-primary text-white'
                    : 'bg-gray-700 text-gray-300'
                }`}
              >
                Upgrade Workshop
              </button>
            </div>
          </div>

          <div className="mt-8 grid gap-6 lg:grid-cols-[1.15fr_0.85fr]">
            <div className="space-y-6">
              <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-4">
                <div className="flex flex-wrap items-center gap-3">
                  <select
                    value={stationFilter}
                    onChange={(event) => setStationFilter(event.target.value)}
                    className="rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  >
                    <option value="all">All Stations</option>
                    {uiState.stations.map((station) => (
                      <option key={station.id} value={station.id}>
                        {station.name}
                      </option>
                    ))}
                  </select>
                  <select
                    value={tagFilter}
                    onChange={(event) => setTagFilter(event.target.value)}
                    className="rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  >
                    <option value="all">All Tags</option>
                    <option value="ore">Ore</option>
                    <option value="crop">Crop</option>
                  </select>
                  <input
                    type="search"
                    value={searchTerm}
                    onChange={(event) => setSearchTerm(event.target.value)}
                    placeholder="Search recipe or output"
                    className="min-w-[180px] flex-1 rounded-lg border border-yellow-700/30 bg-gray-950/70 px-3 py-2 text-xs text-gray-100"
                  />
                  <label className="flex items-center gap-2 text-xs text-gray-300">
                    <input
                      type="checkbox"
                      checked={showCraftableOnly}
                      onChange={(event) => setShowCraftableOnly(event.target.checked)}
                      className="h-4 w-4 rounded border border-yellow-700/30 bg-gray-950/70"
                    />
                    Craftable only
                  </label>
                  <button
                    type="button"
                    onClick={handleClearFilters}
                    className="rounded-lg border border-yellow-700/30 px-3 py-2 text-xs font-semibold text-yellow-200"
                  >
                    Clear filters
                  </button>
                </div>
                <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
                  <button
                    type="button"
                    onClick={() => setTagFilter('all')}
                    className={`rounded-full border px-3 py-1 uppercase tracking-[0.3em] ${
                      tagFilter === 'all'
                        ? 'border-yellow-500/60 bg-yellow-500/10 text-yellow-200'
                        : 'border-yellow-700/30 text-gray-300'
                    }`}
                  >
                    All
                  </button>
                  <button
                    type="button"
                    onClick={() => setTagFilter('ore')}
                    className={`rounded-full border px-3 py-1 uppercase tracking-[0.3em] ${
                      tagFilter === 'ore'
                        ? 'border-yellow-500/60 bg-yellow-500/10 text-yellow-200'
                        : 'border-yellow-700/30 text-gray-300'
                    }`}
                  >
                    Ore ({tagCounts.ore})
                  </button>
                  <button
                    type="button"
                    onClick={() => setTagFilter('crop')}
                    className={`rounded-full border px-3 py-1 uppercase tracking-[0.3em] ${
                      tagFilter === 'crop'
                        ? 'border-yellow-500/60 bg-yellow-500/10 text-yellow-200'
                        : 'border-yellow-700/30 text-gray-300'
                    }`}
                  >
                    Crop ({tagCounts.crop})
                  </button>
                  <span className="rounded-full border border-yellow-700/30 px-3 py-1 uppercase tracking-[0.3em] text-gray-300">
                    {filteredRecipeCount} shown
                  </span>
                </div>
              </div>
              {unlockedStations.map((station) => (
                stationFilter !== 'all' && stationFilter !== station.id ? null : (
                <div key={station.id} className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-5">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div>
                      <p className="text-xs uppercase tracking-[0.3em] text-gray-400">{station.name}</p>
                      <p className="mt-2 text-lg font-semibold text-white">{station.description}</p>
                    </div>
                    {!station.unlocked ? (
                      <span className="rounded-full border border-yellow-700/40 bg-gray-900/80 px-3 py-1 text-xs text-yellow-200">
                        Unlocks at level {station.unlockLevel}
                      </span>
                    ) : null}
                  </div>

                  {station.unlocked ? (
                    <div className="mt-4 grid gap-3 sm:grid-cols-2">
                      {(uiState.recipes[station.id] || []).map((recipe) => {
                        const quantity = quantities[recipe.id] || 1;
                        if (!shouldShowRecipe(recipe, quantity)) {
                          return null;
                        }
                        const craftable = canCraft(recipe, quantity);
                        const tags = getRecipeTags(recipe);
                        return (
                          <div key={recipe.id} className="rounded-xl border border-yellow-700/20 bg-gray-900/80 p-4">
                            <p className="text-sm font-semibold text-white">{getOutputName(recipe)}</p>
                            <p className="mt-1 text-xs text-gray-400">Requires level {recipe.levelRequired}</p>
                            {tags.length ? (
                              <div className="mt-2 flex flex-wrap gap-2 text-[10px] uppercase tracking-[0.3em] text-yellow-200">
                                {tags.map((tag) => (
                                  <span key={tag} className="rounded-full border border-yellow-700/30 px-2 py-1">
                                    {tag}
                                  </span>
                                ))}
                              </div>
                            ) : null}
                            <div className="mt-3 space-y-1 text-xs text-gray-300">
                              {recipe.inputs.map((input) => (
                                <div key={input.id} className="flex items-center justify-between">
                                  <span>
                                    {input.amount} {getInputName(input)}
                                  </span>
                                  <span className="text-gray-400">Owned: {getOwnedForInput(input)}</span>
                                </div>
                              ))}
                            </div>
                            <div className="mt-3 flex flex-wrap items-center gap-2 text-xs text-gray-400">
                              <span>
                                Duration:{' '}
                                {formatDuration(
                                  recipe.durationMs * quantity * (upgrade?.durationMultiplier || 1)
                                )}
                              </span>
                              <span>·</span>
                              <span>XP: {recipe.xp * quantity}</span>
                            </div>
                            <div className="mt-3 flex flex-wrap items-center gap-2">
                              <input
                                type="number"
                                min="1"
                                value={quantity}
                                onChange={(event) =>
                                  setQuantities((prev) => ({
                                    ...prev,
                                    [recipe.id]: clampQuantity(event.target.value, 1),
                                  }))
                                }
                                className="w-20 rounded-lg border border-yellow-700/30 bg-gray-950/70 px-2 py-1 text-xs text-gray-100"
                              />
                              <button
                                type="button"
                                onClick={() => handleQueue(recipe.id, quantity)}
                                disabled={!craftable}
                                className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                                  craftable ? 'action-primary text-white' : 'bg-gray-700 text-gray-300'
                                }`}
                              >
                                Craft
                              </button>
                              <button
                                type="button"
                                onClick={() => handleQueue(recipe.id, 5)}
                                disabled={!canCraft(recipe, 5)}
                                className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                                  canCraft(recipe, 5) ? 'action-ghost text-yellow-200' : 'bg-gray-700 text-gray-300'
                                }`}
                              >
                                Craft 5
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <p className="mt-4 text-sm text-gray-400">Reach workshop level {station.unlockLevel} to unlock.</p>
                  )}
                </div>
                )
              ))}
            </div>

            <div className="space-y-6">
              <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-5">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Active Queue</p>
                {uiState.jobs.length === 0 ? (
                  <p className="mt-3 text-sm text-gray-300">No crafting jobs queued.</p>
                ) : (
                  <div className="mt-3 space-y-3 text-sm text-gray-300">
                    {uiState.jobs.map((job) => (
                      <div key={job.id} className="rounded-lg border border-yellow-700/20 bg-gray-900/80 p-3">
                        <p className="text-white font-semibold">{getRecipeOutputName(job.recipeId)}</p>
                        <p className="mt-1 text-xs text-gray-400">Quantity: {job.quantity}</p>
                        <p className="mt-2 text-xs text-yellow-200">
                          Ready in {formatDuration(job.remainingMs)}
                        </p>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className="rounded-2xl border border-yellow-700/30 bg-gray-950/70 p-5">
                <p className="text-xs uppercase tracking-[0.3em] text-gray-400">Crafted Inventory</p>
                <div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-xs text-gray-400">
                  <span>Total items: {workshopInventoryTotal}</span>
                  <button
                    type="button"
                    onClick={handleSellAllCrafted}
                    disabled={workshopInventoryTotal <= 0}
                    className={`rounded-lg px-3 py-2 text-xs font-semibold ${
                      workshopInventoryTotal > 0
                        ? 'action-ghost text-yellow-200'
                        : 'bg-gray-700 text-gray-300'
                    }`}
                  >
                    Sell All
                  </button>
                </div>
                {Object.keys(workshopInventory).length === 0 ? (
                  <p className="mt-3 text-sm text-gray-300">No crafted items yet.</p>
                ) : (
                  <div className="mt-3 space-y-3 text-sm text-gray-300">
                    {Object.entries(workshopInventory).map(([itemId, amount]) => {
                      const item = getWorkshopItem(itemId);
                      return (
                        <div key={itemId} className="rounded-lg border border-yellow-700/20 bg-gray-900/80 p-3">
                          <div className="flex items-center justify-between">
                            <p className="text-white font-semibold">{item?.name || itemId}</p>
                            <span className="text-yellow-200">x{amount}</span>
                          </div>
                          <p className="mt-1 text-xs text-gray-400">Sell value: {item?.sellValue || 0} gold</p>
                          <div className="mt-3 flex flex-wrap items-center gap-2">
                            <button
                              type="button"
                              onClick={() => handleSell(itemId, 1)}
                              className="rounded-lg px-3 py-2 text-xs font-semibold text-white action-primary"
                            >
                              Sell 1
                            </button>
                            <button
                              type="button"
                              onClick={() => handleSell(itemId, amount)}
                              className="rounded-lg px-3 py-2 text-xs font-semibold text-yellow-200 action-ghost"
                            >
                              Sell All
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>

          <Link
            to="/dashboard"
            className="mt-8 inline-flex items-center rounded-lg px-4 py-2 text-sm font-semibold text-yellow-200 action-ghost"
          >
            Back to Dashboard
          </Link>
        </div>
      </div>
    </section>
  );
}
